// ── GENERATE TEXT-BASED PI ──
function generateTextPI(orderId: string, companyName: string, items: { name: string; qty: number }[], totalEstimate: number): string {
  const soNum = orderId.split("-")[0].toUpperCase();
  const lines = [
    `PROFORMA INVOICE`,
    ``,
    `SO #: ${soNum}`,
    `Client: ${companyName}`,
    `Date: ${new Date().toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric", timeZone: "Asia/Kolkata" })}`,
    ``,
    `Items:`,
  ];

  items.forEach((item, i) => {
    lines.push(`${i + 1}. ${item.name} x ${item.qty}`);
  });

  lines.push(``);
  if (totalEstimate > 0) {
    const advance = Math.max(Math.round((totalEstimate * 0.2) / 1000) * 1000, 1000);
    lines.push(`Estimated Value: Rs. ${totalEstimate.toLocaleString("en-IN")}`);
    lines.push(`Advance Required (20%): Rs. ${advance.toLocaleString("en-IN")}`);
  } else {
    lines.push(`Pricing will be confirmed by your Sales Executive.`);
  }

  lines.push(``);
  lines.push(`Track your order: ${PORTAL_URL}/track?token=${orderId}`);
  lines.push(``);
  lines.push(`Status: Pre-Approved | Advance Pending`);
  lines.push(``);
  lines.push(`— Oasis Operations`);

  return lines.join("\n");
}

type ParsedOrderItem = { productId: string; productName: string; quantity: number; confidence: number };

async function findHeldClarificationOrder(
  supabaseAdmin: SupabaseAdminClient,
  companyId: string,
): Promise<{ id: string } | null> {
  const cutoff = new Date(Date.now() - HELD_ORDER_MAX_AGE_MS).toISOString();
  const { data } = await supabaseAdmin
    .from("orders")
    .select("id")
    .eq("company_id", companyId)
    .eq("needs_clarification", true)
    .eq("status", "awaiting_clarification")
    .or("is_waste.is.null,is_waste.eq.false")
    .gte("created_at", cutoff)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  return data?.id ? { id: data.id } : null;
}

/** Strict: no digits (avoid qty corrections), short, confirmation-only phrasing. */
function isConfirmOnlyFollowup(text: string): boolean {
  const t = text.trim().toLowerCase().replace(/[.!?,]+$/g, "").replace(/\s+/g, " ");
  if (!t || t.length > CONFIRM_FOLLOWUP_MAX_CHARS) return false;
  if (/\d/.test(t)) return false;
  const allowed = new Set([
    "yes", "yep", "yeah", "ok", "okay",
    "confirmed", "confirm", "proceed", "correct",
    "go ahead", "thats fine", "that's fine", "fine",
    "noted", "approved", "alright", "all right",
  ]);
  if (allowed.has(t)) return true;
  const words = t.split(/\s+/);
  return words.length === 1 && allowed.has(words[0]);
}

async function sendPiNotificationsAndCrm(args: {
  supabaseAdmin: SupabaseAdminClient;
  draftOrderId: string;
  companyName: string;
  phone91: string;
  companyId: string;
  accountManagerId: string | null;
  messageBody: string;
  piItems: { name: string; qty: number }[];
  totalWithGst: number;
  isShadowClient: boolean;
  crmOutcome: string;
  crmNotesSuffix: string;
}): Promise<boolean> {
  const {
    supabaseAdmin, draftOrderId, companyName, phone91, companyId, accountManagerId,
    messageBody, piItems, totalWithGst, isShadowClient, crmOutcome, crmNotesSuffix,
  } = args;

  let piSent = false;
  if (piItems.length > 0) {
    const piText = generateTextPI(draftOrderId, companyName, piItems, totalWithGst);
    await sendReply(phone91, piText, supabaseAdmin, companyId);
    piSent = true;
    console.log(`PI sent to ${phone91} for order ${draftOrderId}`);
  } else {
    const ackMsg = [
      `Oasis Operations has created your draft sales order.`,
      ``,
      `Reference: SO #${draftOrderId.split("-")[0].toUpperCase()}`,
      ``,
      `Our team will share the next update shortly.`,
      ``,
      `— Oasis Operations`,
    ].join("\n");
    await sendReply(phone91, ackMsg, supabaseAdmin, companyId);
  }

  if (accountManagerId) {
    await supabaseAdmin.from("notifications").insert({
      user_id: accountManagerId,
      type: "whatsapp_order",
      message: `New WhatsApp Draft Order from ${companyName}${piItems.length > 0 ? ` - ${piItems.map((i) => `${i.name} x ${i.qty}`).join(", ")}` : ""}. Review now.`,
      is_read: false,
    });
  }

  const { data: admins } = await supabaseAdmin
    .from("users").select("id")
    .in("role", ["admin", "super_admin", "ADMIN", "SUPER_ADMIN"])
    .limit(5);
  for (const admin of admins || []) {
    if (admin.id === accountManagerId) continue;
    await supabaseAdmin.from("notifications").insert({
      user_id: admin.id,
      type: "whatsapp_order",
      message: `WhatsApp Draft from ${companyName}: "${messageBody.substring(0, 100)}"`,
      is_read: false,
    });
  }

  await supabaseAdmin.from("client_interactions").insert({
    company_id: companyId,
    executive_id: accountManagerId,
    interaction_type: "whatsapp",
    notes: `[SYSTEM_AI] ${crmNotesSuffix} ${isShadowClient ? "Shadow client." : ""} ${piSent ? "PI sent via WhatsApp." : ""}`,
    outcome: crmOutcome,
  });

  return piSent;
}

async function resolveHeldOrderConfirm(args: {
  supabaseAdmin: SupabaseAdminClient;
  heldOrderId: string;
  companyName: string;
  phone91: string;
  companyId: string;
  accountManagerId: string | null;
  messageBody: string;
  products: { id: string; name: string; sku?: string | null; base_price?: number | null; price_b2b?: number | null; price_per_kg?: number | null; wholesale_price?: number | null; price_wholesale?: number | null }[];
  isShadowClient: boolean;
}): Promise<boolean> {
  const { supabaseAdmin, heldOrderId, companyName, phone91, companyId, accountManagerId, messageBody, products, isShadowClient } = args;

  const { data: rows } = await supabaseAdmin
    .from("order_items")
    .select("product_id, quantity")
    .eq("order_id", heldOrderId);
  if (!rows || rows.length === 0) return false;

  let estimatedTotal = 0;
  const piItems: { name: string; qty: number }[] = [];
  for (const row of rows) {
    const prod = products.find((p) => p.id === row.product_id);
    const name = prod?.name || "Item";
    const qty = Number(row.quantity) || 0;
    piItems.push({ name, qty });
    if (prod) {
      const price = prod.price_b2b || prod.base_price || prod.price_per_kg || prod.wholesale_price || prod.price_wholesale || 0;
      estimatedTotal += price * qty;
    }
  }

  const minConf = 1;
  const totalWithGst = Math.round(estimatedTotal * 1.18);
  const advanceRequired = Math.max(Math.round((totalWithGst * 0.2) / 1000) * 1000, 1000);

  await supabaseAdmin.from("orders").update({
    needs_clarification: false,
    status: "draft",
    parser_confidence: minConf,
    sales_order_value: totalWithGst,
    advance_required: advanceRequired,
  }).eq("id", heldOrderId);

  await sendPiNotificationsAndCrm({
    supabaseAdmin,
    draftOrderId: heldOrderId,
    companyName,
    phone91,
    companyId,
    accountManagerId,
    messageBody,
    piItems,
    totalWithGst,
    isShadowClient,
    crmOutcome: "clarification_resolved",
    crmNotesSuffix: `Clarification hold cleared (customer confirm). Order ${heldOrderId.slice(0, 8)}. Items: ${piItems.map((i) => `${i.name} x ${i.qty}`).join(", ")}.`,
  });

  return true;
}

async function resolveHeldOrderHighConfParse(args: {
  supabaseAdmin: SupabaseAdminClient;
  heldOrderId: string;
  companyName: string;
  phone91: string;
  companyId: string;
  accountManagerId: string | null;
  messageBody: string;
  orderItems: ParsedOrderItem[];
  products: { id: string; name: string; sku?: string | null; base_price?: number | null; price_b2b?: number | null; price_per_kg?: number | null; wholesale_price?: number | null; price_wholesale?: number | null }[];
  isShadowClient: boolean;
}): Promise<boolean> {
  const { supabaseAdmin, heldOrderId, companyName, phone91, companyId, accountManagerId, messageBody, orderItems, products, isShadowClient } = args;

  await supabaseAdmin.from("order_items").delete().eq("order_id", heldOrderId);

  let estimatedTotal = 0;
  const piItems: { name: string; qty: number }[] = [];
  const minConf = Math.min(...orderItems.map((i) => i.confidence));

  for (const item of orderItems) {
    await supabaseAdmin.from("order_items").insert({
      order_id: heldOrderId,
      product_id: item.productId,
      quantity: item.quantity,
      notes: `WhatsApp AI (confidence: ${(item.confidence * 100).toFixed(0)}%): "${messageBody.substring(0, 200)}"`,
    });
    const prod = products.find((p) => p.id === item.productId);
    if (prod) {
      const price = prod.price_b2b || prod.base_price || prod.price_per_kg || prod.wholesale_price || prod.price_wholesale || 0;
      estimatedTotal += price * item.quantity;
    }
    piItems.push({ name: item.productName, qty: item.quantity });
  }

  const totalWithGst = Math.round(estimatedTotal * 1.18);
  const advanceRequired = Math.max(Math.round((totalWithGst * 0.2) / 1000) * 1000, 1000);

  await supabaseAdmin.from("orders").update({
    needs_clarification: false,
    status: "draft",
    parser_confidence: minConf,
    sales_order_value: totalWithGst,
    advance_required: advanceRequired,
  }).eq("id", heldOrderId);

  await sendPiNotificationsAndCrm({
    supabaseAdmin,
    draftOrderId: heldOrderId,
    companyName,
    phone91,
    companyId,
    accountManagerId,
    messageBody,
    piItems,
    totalWithGst,
    isShadowClient,
    crmOutcome: "clarification_resolved",
    crmNotesSuffix: `Clarification hold cleared (high-confidence follow-up parse). Order ${heldOrderId.slice(0, 8)}. Items: ${piItems.map((i) => `${i.name} x ${i.qty}`).join(", ")}.`,
  });

  return true;
}

// ── PDF / DOCUMENT PARSING ──
async function parseDocumentForRepeatOrder(
  attachmentUrl: string,
  supabaseAdmin: any
): Promise<{ invoiceRef: string | null; items: { name: string; qty: number }[] }> {
  const result: { invoiceRef: string | null; items: { name: string; qty: number }[] } = {
    invoiceRef: null,
    items: [],
  };

  try {
    const apiKey = Deno.env.get("LOVABLE_API_KEY");
    if (!apiKey) return result;

    const prompt = `You are a document parser for Oasis Baklawa. The customer has sent a previous invoice or purchase order document.

Extract the following from the document URL/reference: ${attachmentUrl}

Return JSON ONLY:
{
  "invoice_ref": "TCF/25-26/XXXX or similar reference number, or null",
  "items": [{"name": "product name as written", "qty": number}]
}

Look for:
- Invoice numbers in TCF/YY-YY/NNNN format
- Product names and quantities from line items
- Any SKU codes`;

    const res = await fetch("https://openrouter.ai/api/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: "google/gemini-3-flash-preview",
        messages: [{ role: "user", content: prompt }],
        response_format: { type: "json_object" },
        max_tokens: 1000,
      }),
    });

    if (res.ok) {
      const data = await res.json();
      const content = data.choices?.[0]?.message?.content || "{}";
      const parsed = JSON.parse(content);
      result.invoiceRef = parsed.invoice_ref || null;
      result.items = (parsed.items || []).flatMap((i: any) => {
        const qty = Number(i.qty);
        return Number.isFinite(qty) && qty > 0 ? [{ name: i.name || "", qty }] : [];
      });
    }
  } catch (e) {
    console.error("Document parse error:", e);
  }

  return result;
}

// ── PAYLOAD EXTRACTION ──
function extractPayloadFields(payload: any) {
  const entry = payload?.entry?.[0]?.changes?.[0]?.value;
  if (entry) {
    const msg = entry?.messages?.[0];
    const contact = entry?.contacts?.[0];
    return {
      senderPhone: msg?.from || contact?.wa_id || "",
      messageBody: msg?.text?.body || msg?.caption || "",
      messageType: msg?.type || "text",
      mediaUrl: msg?.image?.url || msg?.image?.link || msg?.document?.url || msg?.document?.link || msg?.video?.url || null,
      mediaMime: msg?.image?.mime_type || msg?.document?.mime_type || "image/jpeg",
      mediaCount: [msg?.image, msg?.document, msg?.video, msg?.audio].filter(Boolean).length,
      messageId: msg?.id || null,
      profileName: contact?.profile?.name || null,
      timestampSec: msg?.timestamp ?? null,
      conversationKey: msg?.context?.id || null,
    };
  }

  const m91 =
    payload?.payload?.message ? payload.payload :
    payload?.data?.payload?.message ? payload.data.payload :
    payload?.payload && (payload.payload?.mobile || payload.payload?.from || payload.payload?.sender) ? payload.payload :
    null;
  if (m91) {
    const message = m91.message || {};
    const media = message.media || message.image || message.document || message.video || null;
    const text =
      message.text?.body || message.text || message.caption || media?.caption || m91.text || "";
    return {
      senderPhone: m91.mobile || m91.from || m91.sender || m91.contact?.wa_id || "",
      messageBody: typeof text === "string" ? text : (text?.body || ""),
      messageType: message.type || m91.type || (media ? "image" : "text"),
      mediaUrl: media?.url || media?.link || media?.media_url || null,
      mediaMime: media?.mime_type || media?.mimeType || "image/jpeg",
      mediaCount: Array.isArray(message?.attachments) ? message.attachments.length : (media ? 1 : 0),
      messageId: m91._id || m91.id || m91.message_id || message.id || null,
      profileName: m91.sender_name || m91.name || m91.contact?.profile?.name || null,
      timestampSec: m91.timestamp ?? message.timestamp ?? null,
      conversationKey: message?.context?.id || m91?.context?.id || m91?.reply_to_message_id || null,
    };
  }

  const fallbackMessage =
    typeof payload?.body === "string" ? payload.body :
    typeof payload?.data?.body === "string" ? payload.data.body :
    typeof payload?.text?.body === "string" ? payload.text.body :
    typeof payload?.text === "string" ? payload.text :
    typeof payload?.message === "string" ? payload.message :
    "";
  return {
    senderPhone: payload?.from || payload?.sender || payload?.mobile || payload?.data?.from || payload?.contact?.wa_id || payload?.waId || "",
    messageBody: typeof fallbackMessage === "string" ? fallbackMessage : "",
    messageType: payload?.messageType || payload?.type || payload?.data?.type || "text",
    mediaUrl: payload?.mediaUrl || payload?.media_url || payload?.data?.media_url ||
      payload?.image?.url || payload?.document?.url || payload?.data?.image?.url || null,
    mediaMime: payload?.mediaMimeType || payload?.media_mime_type ||
      payload?.image?.mime_type || payload?.document?.mime_type || "image/jpeg",
    mediaCount: Array.isArray(payload?.attachments) ? payload.attachments.length :
      Array.isArray(payload?.data?.attachments) ? payload.data.attachments.length :
      (payload?.mediaUrl || payload?.media_url || payload?.image || payload?.document ? 1 : 0),
    messageId: payload?.messageId || payload?.id || payload?.message_id || null,
    profileName: payload?.pushName || payload?.profileName || payload?.contact?.name || payload?.sender_name || null,
    timestampSec: payload?.timestamp ?? payload?.data?.timestamp ?? null,
    conversationKey: payload?.context?.id || payload?.reply_to_message_id || payload?.data?.context?.id || null,
  };
}

async function findOrCreateWhatsappContact(
  supabaseAdmin: SupabaseAdminClient,
  phoneDigits: string,
  waContactId?: string | null,
): Promise<string | null> {
  if (!phoneDigits) return null;
  try {
    const existing = await supabaseAdmin
      .from("whatsapp_contacts")
      .select("id")
      .eq("phone_number", phoneDigits)
      .maybeSingle();
    if (existing.data?.id) return existing.data.id;

    const created = await supabaseAdmin
      .from("whatsapp_contacts")
      .insert({
        phone_number: phoneDigits,
        wa_contact_id: waContactId || phoneDigits,
      })
      .select("id")
      .single();
    if (created.error) {
      console.warn("[whatsapp-webhook] whatsapp_contacts insert:", created.error.message);
      return null;
    }
    return created.data?.id ?? null;
  } catch (e) {
    console.warn("[whatsapp-webhook] findOrCreateWhatsappContact:", e);
    return null;
  }
}

function triggerMessageStitcherNonBlocking(): void {
  const baseUrl = Deno.env.get("SUPABASE_URL")?.replace(/\/$/, "");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!baseUrl || !serviceKey) return;
  void fetch(`${baseUrl}/functions/v1/whatsapp-message-stitcher`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${serviceKey}`,
    },
    body: JSON.stringify({ trigger: "webhook" }),
  }).catch((err) =>
    console.warn(`[whatsapp-webhook] Stitcher call failed (non-blocking): ${err}`)
  );
}

/**
 * True only when a previous attempt finished every required step for this provider message.
 * Anything else - no receipt, a lookup error, a thrown exception - means "not known complete",
 * so the idempotent pipeline runs again. Correctness never depends on this lookup; it only
 * lets a genuinely completed message be acknowledged without repeating work.
 */
async function isInboundProcessingComplete(
  supabaseAdmin: SupabaseAdminClient,
  providerMessageId: string,
): Promise<boolean> {
  try {
    const { data, error } = await supabaseAdmin
      .from("debug_webhooks")
      .select("id")
      .eq("wamid", providerMessageId)
      .eq("direction", INBOUND_COMPLETION_DIRECTION)
      .limit(1)
      .maybeSingle();
    if (error) {
      console.error("[whatsapp-webhook] completion receipt lookup failed:", error.code ?? "unknown");
      return false;
    }
    return Boolean(data?.id);
  } catch (e) {
    console.error("[whatsapp-webhook] completion receipt lookup threw:", e instanceof Error ? e.name : "unknown");
    return false;
  }
}

/** Best effort: a missing receipt only costs one extra idempotent replay, never correctness. */
async function recordInboundProcessingComplete(
  supabaseAdmin: SupabaseAdminClient,
  providerMessageId: string,
  phone: string | null,
): Promise<void> {
  try {
    const { error } = await supabaseAdmin.from("debug_webhooks").insert({
      direction: INBOUND_COMPLETION_DIRECTION,
      raw_payload: { receipt: "wa450-inbound-complete" },
      phone_number: phone,
      wamid: providerMessageId,
      processed: true,
      error_message: null,
    });
    if (error) console.error("[whatsapp-webhook] completion receipt write failed:", error.code ?? "unknown");
  } catch (e) {
    console.error("[whatsapp-webhook] completion receipt write threw:", e instanceof Error ? e.name : "unknown");
  }
}

// ══════════════════════════════════════════════════
// MAIN HANDLER
// ══════════════════════════════════════════════════
export async function handleWebhookRequest(req: Request): Promise<Response> {
  if (req.method === "GET") {
    const url = new URL(req.url);
    const challengeParamNames = ["challange", "challenge", "hub.challenge", "hub_challenge"];
    const tokenParamNames = ["echo", "hub.verify_token", "verify_token", "token"];
    const challengeEntry = Array.from(url.searchParams.entries()).find(([key]) =>
      challengeParamNames.includes(key.toLowerCase())
    );
    if (challengeEntry) {
      const tokenEntry = Array.from(url.searchParams.entries()).find(([key]) =>
        tokenParamNames.includes(key.toLowerCase())
      );
      const verification = verifyChallengeToken(
        tokenEntry?.[1] ?? null,
        Deno.env.get("WHATSAPP_WEBHOOK_VERIFY_TOKEN"),
      );
      if (!verification.ok) {
        return new Response(JSON.stringify({ error: verification.code }), {
          status: verification.status,
          headers: safeWebhookHeaders(),
        });
      }
      return new Response(challengeEntry[1], {
        status: 200,
        headers: safeWebhookHeaders("text/plain; charset=utf-8"),
      });
    }
    return new Response("Oasis OS Webhook Active", {
      status: 200,
      headers: safeWebhookHeaders("text/plain; charset=utf-8"),
    });
  }

  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: safeWebhookHeaders() });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "method_not_allowed" }), {
      status: 405,
      headers: safeWebhookHeaders(),
    });
  }

  const rawBody = new Uint8Array(await req.arrayBuffer());
  let boundary: Awaited<ReturnType<typeof authenticateAndParseWebhook>>;
  try {
    boundary = await authenticateAndParseWebhook({
      rawBody,
      requestUrl: req.url,
      signatureHeader: req.headers.get("x-hub-signature-256"),
      verifyToken: Deno.env.get("WHATSAPP_WEBHOOK_VERIFY_TOKEN"),
      appSecret: Deno.env.get("WHATSAPP_META_APP_SECRET") || Deno.env.get("WHATSAPP_APP_SECRET"),
    });
  } catch (error) {
    const code = error instanceof Error ? error.message : "WA_WEBHOOK_BOUNDARY_FAILED";
    console.error("[WA_BOUNDARY]", code.slice(0, 120));
    return new Response(JSON.stringify({ ok: false, error: "webhook_boundary_failed" }), {
      status: 503,
      headers: safeWebhookHeaders(),
    });
  }

  if (!boundary.ok) {
    return new Response(JSON.stringify({ error: boundary.code }), {
      status: boundary.status,
      headers: safeWebhookHeaders(),
    });
  }

  const rootPayload = boundary.payload;
  const supabaseAdmin = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  const statusQuarantineCount = boundary.statusQuarantined.length;
  if (statusQuarantineCount > 0) {
    // Only authenticated callbacks reach this point. Record bounded, PII-free
    // diagnostics durably before ACK; console output alone is not quarantine.
    const reasonHistogram = boundary.statusQuarantined.reduce<Record<string, number>>((acc, item) => {
      acc[item.reason] = (acc[item.reason] ?? 0) + 1;
      return acc;
    }, {});
    try {
      const digest = await crypto.subtle.digest("SHA-256", rawBody);
      const contentHash = Array.from(new Uint8Array(digest))
        .map((part) => part.toString(16).padStart(2, "0")).join("");
      const { error: auditError } = await supabaseAdmin.from("debug_webhooks").insert({
        direction: "provider_status_malformed",
        processed: false,
        discard_reason: "malformed_status_elements_requires_review",
        raw_payload: {
          content_sha256: contentHash,
          quarantined_diagnostics: statusQuarantineCount,
          reason_histogram: reasonHistogram,
          redacted: true,
        },
      });
      if (auditError) {
        console.error("[WA_STATUS_QUARANTINE] audit write failed:", auditError.code ?? "unknown");
        throw new Error("WA_STATUS_MALFORMED_AUDIT_WRITE_FAILED");
      }
      console.log(`[WA_STATUS_QUARANTINE] durable audit recorded count=${statusQuarantineCount}`);
    } catch (error) {
      console.error(
        "[WA_STATUS_QUARANTINE] audit failed, returning 503:",
        error instanceof Error ? error.name : "unknown",
      );
      // Never acknowledge malformed provider data unless the audit is stored.
      return new Response(JSON.stringify({ ok: false, error: "malformed_status_audit_failed" }), {
        status: 503,
        headers: safeWebhookHeaders(),
      });
    }
  }

  let persistedStatusBatch:
    | { count: number; updated: number; ignored: number; unmatched: number; quarantined: number }
    | null = null;

  if (boundary.statusEvents.length > 0) {
    try {
      persistedStatusBatch = await persistOperatorReplyProviderStatusBatch(
        supabaseAdmin, boundary.statusEvents,
      );
    } catch (error) {
      const code = error instanceof Error ? error.message : "WA_STATUS_PERSIST_FAILED";
      console.error("[WA_STATUS]", code.slice(0, 180));
      return new Response(
        JSON.stringify({ ok: false, error: "status_persistence_failed" }),
        { status: 503, headers: safeWebhookHeaders() },
      );
    }

    const containsInbound = payloadContainsInboundMessages(rootPayload);
    if (!containsInbound) {
      console.log(
        `[WA_STATUS] callbacks=${persistedStatusBatch.count} updated=${persistedStatusBatch.updated}`,
      );
      return new Response(
        JSON.stringify({
          ok: true,
          event: "status",
          ...persistedStatusBatch,
          ...(statusQuarantineCount ? { quarantined_status_elements: statusQuarantineCount } : {}),
        }),
        { status: 200, headers: safeWebhookHeaders() },
      );
    }
  }

  const inboundPayloads = payloadContainsInboundMessages(rootPayload)
    ? enumerateInboundPayloads(rootPayload)
    : [rootPayload];

  const inboundResults: { status: number; body: Record<string, unknown> }[] = [];

  for (const inboundPayload of inboundPayloads) {
    const payload = inboundPayload;
    const inboundReturn = (response: Response): never => {
      throw { tag: "inbound_response" as const, response };
    };
    try {
    // WA-1: legacy webhook order mutation is permanently quarantined. Promotion belongs to
    // the governed Core sales_order_drafts RPC and cannot be re-enabled by environment.
    const waAutoOrderWritesEnabled = false;
    const waOwnerReassignmentEnabled = isWaWebhookOwnerReassignmentEnabled((k) => Deno.env.get(k));

    const { senderPhone, messageBody, messageType, mediaUrl, mediaMime, mediaCount, messageId, profileName, timestampSec, conversationKey } =
      extractPayloadFields(payload);

    const last10 = normalizePhone(senderPhone);
    const phone91 = to91(senderPhone);

    const noiseTypes = new Set(["reaction", "unsupported", "system", "ephemeral", "sticker_reaction"]);
    const isNoise = noiseTypes.has((messageType || "").toLowerCase());
    const isEmpty = !messageBody && !mediaUrl;
    if (isNoise || isEmpty) {
      try {
        await supabaseAdmin.from("debug_webhooks").insert({
          direction: "inbound",
          raw_payload: payload,
          phone_number: phone91 || senderPhone || null,
          wamid: messageId || null,
          processed: true,
          discard_reason: isNoise ? `noise_${messageType}` : "empty_body",
          error_message: isNoise ? `Discarded ${messageType} (no order intent)` : "Empty payload — nothing to parse",
        });
      } catch (_) { /* best-effort log */ }
      inboundReturn(new Response(JSON.stringify({ ok: true, discarded: isNoise ? messageType : "empty" }), {
        status: 200, headers: safeWebhookHeaders(),
      }));
    }

    // A durable whatsapp_messages row proves ownership, not completion: the buffer, dispute and
    // media steps run around it. Only a completion receipt lets a retry be acknowledged as a
    // plain duplicate; otherwise the idempotent pipeline below resumes the unfinished work.
    if (messageId && await isInboundProcessingComplete(supabaseAdmin, messageId)) {
      console.log("[WAMID_DEDUP] Discarding completed duplicate");
      await supabaseAdmin.from("debug_webhooks").insert({
        direction: "inbound",
        raw_payload: payload,
        phone_number: phone91 || senderPhone || null,
        wamid: messageId,
        processed: true,
        discard_reason: "duplicate_wamid",
        error_message: "Duplicate WhatsApp message ID — processing already completed",
      });
      inboundReturn(new Response(JSON.stringify({ ok: true, discarded: "duplicate_wamid" }), {
        status: 200, headers: safeWebhookHeaders(),
      }));
    }

    const { data: webhookRow } = await supabaseAdmin.from("debug_webhooks").insert({
      direction: "inbound",
      raw_payload: payload,
      phone_number: phone91 || senderPhone || null,
      wamid: messageId || null,
      error_message: null,
      processed: false,
    }).select("id").maybeSingle();

    // ── BANYAN BUFFER: stash this message for the Central Parser (60s debounce) ──
    if (last10 && (messageBody || mediaUrl)) {
      // The buffer feeds the Central Parser, so it is part of the accepted-processing contract:
      // a failed write must not be acknowledged (the provider retry re-attempts it; the stable
      // primary key makes a repeat write a harmless 23505).
      let bufferPersisted = true;
      try {
        const { error: bufferError } = await supabaseAdmin.from("whatsapp_buffer").insert({
          ...(messageId ? { id: await stableInboundBufferUuid(messageId) } : {}),
          sender_phone: last10,
          sender_name: profileName,
          message_type: messageType || "text",
          text_content: messageBody || null,
          media_url: mediaUrl,
          media_mime_type: mediaMime,
          raw_payload: payload,
          webhook_id: (webhookRow as any)?.id || null,
          bundle_status: "pending",
        });
        if (bufferError && bufferError.code !== "23505") {
          console.error("[whatsapp-webhook] buffer insert failed:", bufferError.code ?? "unknown");
          bufferPersisted = false;
        }
      } catch (bufErr) {
        console.error("[whatsapp-webhook] buffer insert threw:", bufErr instanceof Error ? bufErr.name : "unknown");
        bufferPersisted = false;
      }
      if (!bufferPersisted) {
        inboundReturn(new Response(JSON.stringify({ error: "buffer_persistence_failed" }), {
          status: 503, headers: safeWebhookHeaders(),
        }));
      }
    }


    // ── INTENT CLASSIFICATION ──
    const messageIntentRaw = classifyMessageIntent(
      messageBody || "",
      messageType || "",
      mediaMime || ""
    );

    let messageIntent = messageIntentRaw;
    let hasOrderIntent = false;
    if (messageIntentRaw !== "INTERNAL_NOTE") {
      const msgLowerForOrder = (messageBody || "").toLowerCase();
      hasOrderIntent =
        messageIntentRaw !== "PACKAGING_MATERIAL_REQUEST" &&
        ORDER_INTENT_KEYWORDS.some((kw) => msgLowerForOrder.includes(kw));
      if (messageIntentRaw === "OTHER" && hasOrderIntent) {
        messageIntent = "ORDER";
      }
    }

    const commercialRiskReason = hasOrderIntent
      ? "ORDER_KEYWORD"
      : messageIntentRaw === "PURCHASE_ORDER_DOCUMENT"
      ? "PURCHASE_ORDER_DOCUMENT"
      : messageIntentRaw === "SO_REFERENCE"
      ? "SALES_ORDER_REFERENCE"
      : null;

    // ── STUDIO INBOX FAN-OUT (durable intake; failures must not break legacy ERP path) ──
    if (messageId && (messageBody?.trim() || mediaUrl)) {
      await fanOutToStudioInbox({
        supabaseAdmin,
        providerMessageId: messageId,
        senderPhone: phone91,
        senderName: profileName,
        messageBody: messageBody || "",
        messageType: messageType || "text",
        mediaCount,
        conversationKey: conversationKey || messageId,
        rawPayload: payload,
        timestampSec,
        orderLikeHint: commercialRiskReason !== null,
        commercialRiskReason,
      });
    }

    console.log(`[INTENT] ${messageIntent} | phone=${phone91} | type=${messageType}`);

    if ((webhookRow as any)?.id) {
      void supabaseAdmin
        .from("debug_webhooks")
        .update({ message_intent: messageIntent })
        .eq("id", (webhookRow as any).id)
        .then(
          () => { /* no-op */ },
          (e: unknown) => console.error("intent write failed:", e),
        );
    }

    if (messageIntentRaw === "INTERNAL_NOTE") {
      if ((webhookRow as any)?.id) {
        await supabaseAdmin
          .from("debug_webhooks")
          .update({ processed: true, discard_reason: "internal_note" })
          .eq("id", (webhookRow as any).id);
      }
      inboundReturn(new Response(JSON.stringify({ ok: true, intent: "INTERNAL_NOTE", skipped: true }), {
        status: 200, headers: safeWebhookHeaders(),
      }));
    }

    try {
      const txt = (messageBody || "").toLowerCase().trim();
      const isDispute =
        txt.includes("request correction") ||
        txt.includes("ledger dispute") ||
        txt.includes("ledger correction") ||
        txt.includes("account mismatch") ||
        txt === "disputed" ||
        txt === "dispute";
      if (last10 && isDispute) {
        const disputeContactId = await findOrCreateWhatsappContact(supabaseAdmin, phone91, phone91);
        const disputeResolution = disputeContactId
          ? await resolveWebhookCompany(supabaseAdmin, {
            contactId: disputeContactId,
            profileName,
            messageBody,
            senderIsStaffProxy: false,
          })
          : null;
        const comp = disputeResolution?.companyId
          ? { id: disputeResolution.companyId, business_name: disputeResolution.companyName }
          : null;
        if (comp?.id) {
          const { data: latestLedger } = await supabaseAdmin
            .from("bi_monthly_ledgers")
            .select("id")
            .eq("company_id", comp.id)
            .order("generated_at", { ascending: false })
            .limit(1)
            .maybeSingle();
          if (latestLedger?.id) {
            // Best effort by design, with a stable id + idempotency key per provider message so a
            // retry or concurrent delivery can never raise a second dispute. Production's
            // trg_ledger_disputes_governed_write rejects direct inserts
            // (LEDGER_DISPUTE_GOVERNED_WRITE_REQUIRED) and raise_ledger_dispute_v1 is not callable
            // by service_role, so this insert cannot succeed today. Failing the request on it
            // would return a permanent 5xx for every dispute-worded message once ledgers exist.
            // The governed service-role intake is tracked as a separate Core change.
            const disputeKey = messageId ? await stableInboundEffectUuid("dispute", messageId) : null;
            const { error: disputeError } = await supabaseAdmin.from("ledger_disputes").insert({
              ...(disputeKey ? { id: disputeKey, idempotency_key: `wa450:dispute:${disputeKey}` } : {}),
              ledger_id: latestLedger.id,
              company_id: comp.id,
              raised_via: "whatsapp",
              description: messageBody?.slice(0, 500) || null,
              status: "open",
            });
            if (disputeError && disputeError.code !== "23505") {
              console.error("[whatsapp-webhook] ledger dispute not stored:", disputeError.code ?? "unknown");
            }
            await supabaseAdmin
              .from("bi_monthly_ledgers")
              .update({ status: "disputed" })
              .eq("id", latestLedger.id);
            // Core-C already owns non-order receipts. Never send a duplicate
            // inline dispute acknowledgement outside the governed outbox.
            console.log("[WA-GOV] Ledger dispute saved; governed non-order reply path owns any acknowledgement");
          }
        }
      }
    } catch (dispErr) {
      console.error("Dispute keyword detection error:", dispErr instanceof Error ? dispErr.message : "unknown");
    }

    const direction: string = (payload?.direction as string) || (payload?.statuses ? "status" : "");
    if (direction === "outgoing" || direction === "sent" || direction === "status") {
      if (payload?.statuses) {
        console.log("Status update received, skipping:", JSON.stringify(payload.statuses).substring(0, 200));
      }
      inboundReturn(new Response(JSON.stringify({ ok: true, skipped: "outgoing/status" }), {
        status: 200, headers: safeWebhookHeaders(),
      }));
    }

    let persistenceFailed = false;
    const requiresDurableOwnership = Boolean(phone91 && (messageBody || mediaUrl));

    try {
      if (requiresDurableOwnership) {
        const contactId = await findOrCreateWhatsappContact(supabaseAdmin, phone91, phone91);
        let insertError: { code?: string; message?: string } | null = null;

        if (contactId) {
          const tsSec =
            timestampSec != null && timestampSec !== ""
              ? Number(timestampSec)
              : NaN;
          const message_timestamp =
            Number.isFinite(tsSec) && tsSec > 0
              ? new Date(tsSec * 1000)
              : new Date();

          const { error } = await supabaseAdmin
            .from("whatsapp_messages")
            .insert({
              contact_id: contactId,
              order_id: null,
              direction: "inbound",
              message_type: messageType || "text",
              content: messageBody || "",
              media_url: mediaUrl || null,
              provider: "whatsapp",
              provider_message_id: messageId,
              status: "received",
              message_timestamp,
              is_raw: true,
              packet_id: null,
            })
            .select("id")
            .single();
          insertError = error;

          if (!insertError) {
            triggerMessageStitcherNonBlocking();
          } else if (insertError.code === "23505") {
            // Durably owned by an earlier attempt that did not record completion: resume.
            console.log("[whatsapp-webhook] whatsapp_messages already owned — resuming unfinished processing");
            triggerMessageStitcherNonBlocking();
          } else {
            console.error(
              "[whatsapp-webhook] whatsapp_messages insert failed (non-duplicate):",
              insertError,
            );
          }
        }

        persistenceFailed = durablePersistenceFailed(
          requiresDurableOwnership,
          contactId,
          insertError,
          false,
        );
      }
    } catch (wmErr) {
      console.error("[whatsapp-webhook] durable persistence block failed:", wmErr);
      persistenceFailed = requiresDurableOwnership;
    }

    if (persistenceFailed) {
      inboundReturn(new Response(
        JSON.stringify({ error: "durable_persistence_failed" }),
        { status: 503, headers: safeWebhookHeaders() },
      ));
    }

    if (!senderPhone && !mediaUrl) {
      inboundReturn(new Response(JSON.stringify({ ok: true, skipped: "no sender" }), {
        status: 200, headers: safeWebhookHeaders(),
      }));
    }

    const sender = await classifySender(last10, supabaseAdmin);
    console.log(`Sender classified: ${sender.type} (${sender.name || "unknown"}) phone=${phone91}, isSalesExec=${sender.isSalesExec}`);

    const senderIsStaffProxy = sender.type === "staff" && !!sender.userId;
    const senderIsSalesExec = sender.type === "staff" && sender.isSalesExec && sender.userId;
    const payloadIdentity = extractPayloadIdentityFields(payload as Record<string, unknown>);

    const contactId = await findOrCreateWhatsappContact(supabaseAdmin, phone91, phone91);
    let companyResolution: WebhookCompanyResolution = {
      companyId: null,
      companyName: profileName || "Unknown",
      accountManagerId: null,
      resolutionStatus: "UNRESOLVED",
      matchMethod: null,
      details: { reason: "missing_whatsapp_contact" },
    };

    if (contactId) {
      companyResolution = await resolveWebhookCompany(supabaseAdmin, {
        contactId,
        profileName,
        messageBody,
        senderIsStaffProxy,
        isForwarded: payloadIdentity.isForwarded,
        forwardedFromPhone: payloadIdentity.forwardedFromPhone,
        originalCommunicatorPhone: payloadIdentity.originalCommunicatorPhone,
      });
    }

    let companyId = companyResolution.companyId;
    let companyName = companyResolution.companyName;
    let accountManagerId = companyResolution.accountManagerId;

    if (!companyId && senderIsStaffProxy) {
      console.log(
        `[WA-GOV] Proxy staff sender unresolved: ${sender.name || sender.userId} phone=${phone91} status=${companyResolution.resolutionStatus} method=${companyResolution.matchMethod ?? "none"}`,
      );
    } else if (!companyId) {
      console.log(
        `[WA-GOV] Governed customer unresolved for phone=${phone91} status=${companyResolution.resolutionStatus} method=${companyResolution.matchMethod ?? "none"}`,
      );
    }

    if (
      senderIsSalesExec &&
      companyId &&
      !accountManagerId &&
      waOwnerReassignmentEnabled &&
      sender.userId
    ) {
      accountManagerId = sender.userId;
      await supabaseAdmin.from("companies")
        .update({ account_manager_id: sender.userId })
        .eq("id", companyId);
      console.log(`[WA-GOV] Owner reassignment enabled: auto-assigned ${sender.name} as account manager for ${companyId}`);
    } else if (senderIsSalesExec && companyId && !accountManagerId) {
      console.log(
        `[WA-GOV] Sales exec ${sender.name} proxy for ${companyId}; owner assignment skipped (ENABLE_WA_WEBHOOK_OWNER_REASSIGNMENT=false)`,
      );
    }

    console.log(
      `Governed identity map phone=${phone91} -> company: ${companyName} (${companyId}), status=${companyResolution.resolutionStatus}, method=${companyResolution.matchMethod ?? "none"}, forwarded=${payloadIdentity.isForwarded}, sender: ${sender.type}, salesExec: ${senderIsSalesExec}`,
    );

    let attachmentUrl: string | null = null;
    let documentParseResult: { invoiceRef: string | null; items: { name: string; qty: number }[] } | null = null;
    let mediaProcessingOutcome: "SUCCEEDED" | "UNSUPPORTED" | "CORRUPT" | "UNREADABLE" | "TIMED_OUT" | "FAILED" | null = null;
    let mediaProcessingDetail: Record<string, unknown> = {};

    if (mediaUrl) {
      try {
        const supportedMedia = mediaMime.startsWith("image/") || mediaMime === "application/pdf";
        if (!supportedMedia) {
          mediaProcessingOutcome = "UNSUPPORTED";
          mediaProcessingDetail = { mime_type: mediaMime };
          throw new Error(`unsupported media type: ${mediaMime}`);
        }
        const apiKey = Deno.env.get("CLICK2API_API_KEY");
        const accessToken = Deno.env.get("CLICK2API_ACCESS_TOKEN");
        const mediaRes = await fetch(mediaUrl, {
          headers: {
            ...(apiKey ? { "apikey": apiKey } : {}),
            ...(accessToken ? { "Authorization": `Bearer ${accessToken}` } : {}),
          },
        });
        if (mediaRes.ok) {
          const blob = await mediaRes.arrayBuffer();
          const ext = mediaMime.includes("pdf") ? "pdf" : mediaMime.includes("png") ? "png" : "jpg";
          // Deterministic per provider message: a replay addresses the same object instead of
          // storing another copy. An "already exists" answer means an earlier attempt stored it.
          const filePath = messageId
            ? await inboundMediaObjectName(last10, messageId, ext)
            : `${last10}/${Date.now()}.${ext}`;
          const { error: uploadErr } = await supabaseAdmin.storage
            .from("whatsapp_attachments")
            .upload(filePath, new Uint8Array(blob), { contentType: mediaMime, upsert: false });
          if (!uploadErr || isStorageObjectExistsError(uploadErr)) {
            const { data: urlData } = supabaseAdmin.storage.from("whatsapp_attachments").getPublicUrl(filePath);
            attachmentUrl = urlData?.publicUrl || filePath;
            if ((webhookRow as any)?.id && attachmentUrl) {
              try {
                await supabaseAdmin
                  .from("debug_webhooks")
                  .update({
                    raw_payload: { ...(payload as any), _oasis_attachment_url: attachmentUrl },
                  } as any)
                  .eq("id", (webhookRow as any).id);
              } catch (patchErr) {
                console.error("debug_webhooks attachment patch failed:", patchErr);
              }
            }
            mediaProcessingOutcome = "SUCCEEDED";
          } else {
            mediaProcessingOutcome = "FAILED";
            mediaProcessingDetail = { stage: "storage_upload", reason: uploadErr.message };
          }

          if (messageType === "document" || mediaMime.includes("pdf")) {
            documentParseResult = await parseDocumentForRepeatOrder(attachmentUrl || filePath, supabaseAdmin);
            if (documentParseResult.invoiceRef) {
              console.log(`Document parsed: Invoice Ref ${documentParseResult.invoiceRef}, Items: ${documentParseResult.items.length}`);
            }
          }
        } else {
          await mediaRes.text();
          mediaProcessingOutcome = mediaRes.status === 408 || mediaRes.status === 504 ? "TIMED_OUT" : "FAILED";
          mediaProcessingDetail = { stage: "provider_download", status: mediaRes.status };
        }
      } catch (mediaErr) {
        console.error("Media download failed:", mediaErr);
        mediaProcessingOutcome ??= mediaErr instanceof DOMException && mediaErr.name === "TimeoutError" ? "TIMED_OUT" : "FAILED";
        mediaProcessingDetail = { ...mediaProcessingDetail, error: mediaErr instanceof Error ? mediaErr.message : String(mediaErr) };
      }
      if (mediaCount > 1) {
        mediaProcessingOutcome = "UNSUPPORTED";
        mediaProcessingDetail = { ...mediaProcessingDetail, attachment_count: mediaCount, reason: "MULTI_ATTACHMENT_REQUIRES_HUMAN_REVIEW" };
      }
      if (messageId && commercialRiskReason && mediaProcessingOutcome) {
        const { error: mediaStateError } = await supabaseAdmin.rpc("complete_whatsapp_media_processing", {
          p_provider_message_id: messageId,
          p_state: mediaProcessingOutcome,
          p_attempt_key: `webhook:${messageId}`,
          p_detail: { ...mediaProcessingDetail, attachment_url: attachmentUrl, mime_type: mediaMime },
        });
        if (mediaStateError) throw new Error(`commercial media state persistence failed: ${mediaStateError.message}`);
      }
    }

    const interactionNotes = [
      `[INCOMING${sender.type === "staff" ? " - STAFF: " + sender.name : ""}]`,
      messageBody ? messageBody.substring(0, 1000) : "(media only)",
      attachmentUrl ? `\nAttachment: ${attachmentUrl}` : "",
      documentParseResult?.invoiceRef ? `\nRepeat Order Ref: ${documentParseResult.invoiceRef}` : "",
    ].filter(Boolean).join(" ");

    if (companyId) {
      // Best effort by design: production's client_interactions_interaction_type_check allows
      // only call/visit/email/complaint, so this "whatsapp" note is currently rejected and has
      // never been stored. Making it required would turn every resolved-customer message into a
      // permanent 5xx. The stable id keeps it idempotent once the sink is corrected (tracked
      // separately - needs a governed Core change, not a webhook workaround).
      const interactionId = messageId ? await stableInboundEffectUuid("interaction", messageId) : null;
      const { error: interactionError } = await supabaseAdmin.from("client_interactions").insert({
        ...(interactionId ? { id: interactionId } : {}),
        company_id: companyId,
        executive_id: accountManagerId,
        interaction_type: "whatsapp",
        notes: interactionNotes,
        outcome: "received",
      });
      if (interactionError && interactionError.code !== "23505") {
        console.error("[whatsapp-webhook] client_interactions note not stored:", interactionError.code ?? "unknown");
      }
    }

    let draftOrderId: string | null = null;
    let piSent = false;

    if (hasOrderIntent && companyId && messageBody) {
      if (!waAutoOrderWritesEnabled) {
        console.log(
          `[WA-GOV] Pipeline C auto-order skipped for company ${companyId} (ENABLE_WA_WEBHOOK_AUTO_ORDER_WRITES=false). Inbound capture + Banyan buffer path unchanged.`,
        );
      } else {
      const { data: allProducts } = await supabaseAdmin
        .from("products")
        .select("id, name, sku, base_price, price_b2b, price_wholesale, wholesale_price, price_per_kg")
        .limit(500);

      const { data: aliasRows } = await supabaseAdmin
        .from("product_aliases")
        .select("alias_text, canonical_name, product_id")
        .limit(200);

      const products = allProducts || [];
      const aliases = aliasRows || [];

      console.log(`Products loaded: ${products.length}, Aliases loaded: ${aliases.length}`);

      let skipNewOrderPipeline = false;

      const heldEarly = await findHeldClarificationOrder(supabaseAdmin, companyId);
      if (heldEarly?.id) {
        const trimmed = messageBody.trim();
        let resolvedHere = false;

        if (isConfirmOnlyFollowup(trimmed)) {
          resolvedHere = await resolveHeldOrderConfirm({
            supabaseAdmin,
            heldOrderId: heldEarly.id,
            companyName,
            phone91,
            companyId,
            accountManagerId,
            messageBody,
            products,
            isShadowClient: false,
          });
        } else if (trimmed.length > 0 && trimmed.length <= FOLLOWUP_PARSE_MAX_CHARS) {
          const fuAi = await aiParseOrder(trimmed, products, aliases);
          let fuItems: ParsedOrderItem[] = fuAi.items;
          if (fuItems.length === 0) {
            const matched = aliasMatchProduct(trimmed, products, aliases);
            const qty = parseQuantity(trimmed);
            if (matched && qty !== null) {
              fuItems = [{ productId: matched.id, productName: matched.name, quantity: qty, confidence: 0.7 }];
            }
          }
          if (fuItems.length > 0 && fuItems.every((i) => i.confidence >= HOLD_RELEASE_CONF)) {
            resolvedHere = await resolveHeldOrderHighConfParse({
              supabaseAdmin,
              heldOrderId: heldEarly.id,
              companyName,
              phone91,
              companyId,
              accountManagerId,
              messageBody: trimmed,
              orderItems: fuItems,
              products,
              isShadowClient: false,
            });
          }
        }

        if (resolvedHere) {
          draftOrderId = heldEarly.id;
          piSent = true;
          skipNewOrderPipeline = true;
        } else {
          const neutralHold = [
            `Oasis Operations is still clarifying your pending order (ref ${heldEarly.id.slice(0, 8).toUpperCase()}).`,
            ``,
            `Please reply to our earlier WhatsApp message with the requested details, or send a brief confirmation if the information is already correct.`,
            ``,
            `— Oasis Operations`,
          ].join("\n");
          await sendReply(phone91, neutralHold, supabaseAdmin, companyId);
          skipNewOrderPipeline = true;
        }
      }

      if (!skipNewOrderPipeline) {
        const aiResult = await aiParseOrder(messageBody, products, aliases);
        let orderItems: ParsedOrderItem[] = aiResult.items;

        if (orderItems.length === 0) {
          const matched = aliasMatchProduct(messageBody, products, aliases);
          const qty = parseQuantity(messageBody);
          console.log(`Rule-based match: ${matched ? matched.name : "NONE"}, qty: ${qty}`);
          if (matched && qty !== null) {
            orderItems = [{ productId: matched.id, productName: matched.name, quantity: qty, confidence: 0.7 }];
          }
        }

        if (documentParseResult && documentParseResult.items.length > 0) {
          for (const docItem of documentParseResult.items) {
            const matched = aliasMatchProduct(docItem.name, products, aliases);
            if (matched && !orderItems.find((oi) => oi.productId === matched.id)) {
              orderItems.push({
                productId: matched.id,
                productName: matched.name,
                quantity: docItem.qty,
                confidence: 0.8,
              });
            }
          }
        }

        console.log(`Order items resolved: ${orderItems.length}`);

        const lowConfidenceItems = orderItems.filter((i) => i.confidence < CLARIFICATION_LOW_CONF);

        if (lowConfidenceItems.length > 0 && orderItems.length > 0) {
          const clarificationLines = lowConfidenceItems.map(
            (i) => `- "${i.productName}" x ${i.quantity}`,
          );
          const clarifyMsg = [
            `Oasis Operations has logged your order request and requires one clarification before sharing pricing:`,
            ``,
            `Please confirm the specific variant or quantity for:`,
            ``,
            ...clarificationLines,
            ``,
            `Please reply with corrections, or send a brief confirmation if the above is correct.`,
            ``,
            `— Oasis Operations`,
          ].join("\n");

          await sendReply(phone91, clarifyMsg, supabaseAdmin, companyId);
          console.log(`Clarification hold: outbound clarification only (${lowConfidenceItems.length} low-confidence lines)`);

          const minParserConf = Math.min(...orderItems.map((i) => i.confidence));
          let heldTargetId: string | null = null;
          const existingHeld = await findHeldClarificationOrder(supabaseAdmin, companyId);

          if (existingHeld?.id) {
            heldTargetId = existingHeld.id;
            await supabaseAdmin.from("order_items").delete().eq("order_id", heldTargetId);
            await supabaseAdmin.from("orders").update({
              needs_clarification: true,
              status: "awaiting_clarification",
              parser_confidence: minParserConf,
              dispatch_urgency: "standard",
              payment_status: "awaiting_advance",
            }).eq("id", heldTargetId);
          } else {
            const { data: ins, error: insErr } = await supabaseAdmin
              .from("orders")
              .insert({
                company_id: companyId,
                status: "awaiting_clarification",
                needs_clarification: true,
                parser_confidence: minParserConf,
                dispatch_urgency: "standard",
                payment_status: "awaiting_advance",
              })
              .select("id")
              .single();
            if (!insErr && ins?.id) heldTargetId = ins.id;
          }

          if (heldTargetId) {
            draftOrderId = heldTargetId;
            let estimatedTotal = 0;
            const piItems: { name: string; qty: number }[] = [];

            for (const item of orderItems) {
              await supabaseAdmin.from("order_items").insert({
                order_id: heldTargetId,
                product_id: item.productId,
                quantity: item.quantity,
                notes: `WhatsApp AI (confidence: ${(item.confidence * 100).toFixed(0)}%): "${messageBody.substring(0, 200)}"`,
              });
              const prod = products.find((p) => p.id === item.productId);
              if (prod) {
                const price = prod.price_b2b || prod.base_price || prod.price_per_kg || prod.wholesale_price || prod.price_wholesale || 0;
                estimatedTotal += price * item.quantity;
              }
              piItems.push({ name: item.productName, qty: item.quantity });
            }

            const totalWithGst = Math.round(estimatedTotal * 1.18);
            const advanceRequired = Math.max(Math.round((totalWithGst * 0.2) / 1000) * 1000, 1000);
            await supabaseAdmin.from("orders").update({
              sales_order_value: totalWithGst,
              advance_required: advanceRequired,
            }).eq("id", heldTargetId);

            if (accountManagerId) {
              await supabaseAdmin.from("notifications").insert({
                user_id: accountManagerId,
                type: "whatsapp_order",
                message: `WhatsApp order awaiting clarification from ${companyName}${piItems.length > 0 ? ` — ${piItems.map((i) => `${i.name} x ${i.qty}`).join(", ")}` : ""}. No PI sent yet.`,
                is_read: false,
              });
            }

            const { data: adminsHold } = await supabaseAdmin
              .from("users").select("id")
              .in("role", ["admin", "super_admin", "ADMIN", "SUPER_ADMIN"])
              .limit(5);
            for (const admin of adminsHold || []) {
              if (admin.id === accountManagerId) continue;
              await supabaseAdmin.from("notifications").insert({
                user_id: admin.id,
                type: "whatsapp_order",
                message: `Clarification hold: ${companyName} — "${messageBody.substring(0, 100)}"`,
                is_read: false,
              });
            }

            await supabaseAdmin.from("client_interactions").insert({
              company_id: companyId,
              executive_id: accountManagerId,
              interaction_type: "whatsapp",
              notes: `[SYSTEM_AI] Clarification hold ${heldTargetId.slice(0, 8)}. ${piItems.length > 0 ? `Items: ${piItems.map((i) => `${i.name} x ${i.qty}`).join(", ")}.` : ""} Parser min conf ${(minParserConf * 100).toFixed(0)}%. No PI sent.`,
              outcome: existingHeld?.id ? "clarification_hold_updated" : "clarification_hold",
            });
          }
        } else if (orderItems.length > 0 || hasOrderIntent) {
          console.log(`Creating draft order for ${companyId}, items: ${orderItems.length}`);
          const { data: draftOrder, error: orderErr } = await supabaseAdmin
            .from("orders")
            .insert({
              company_id: companyId,
              status: "draft",
              dispatch_urgency: "standard",
              payment_status: "awaiting_advance",
            })
            .select("id")
            .single();

          console.log(`Draft result: ${JSON.stringify(draftOrder)}, err: ${orderErr?.message || "none"}`);
          if (!orderErr && draftOrder) {
            draftOrderId = draftOrder.id;

            let estimatedTotal = 0;
            const piItems: { name: string; qty: number }[] = [];

            for (const item of orderItems) {
              await supabaseAdmin.from("order_items").insert({
                order_id: draftOrder.id,
                product_id: item.productId,
                quantity: item.quantity,
                notes: `WhatsApp AI (confidence: ${(item.confidence * 100).toFixed(0)}%): "${messageBody.substring(0, 200)}"`,
              });

              const prod = products.find((p) => p.id === item.productId);
              if (prod) {
                const price = prod.price_b2b || prod.base_price || prod.price_per_kg || prod.wholesale_price || prod.price_wholesale || 0;
                estimatedTotal += price * item.quantity;
              }
              piItems.push({ name: item.productName, qty: item.quantity });
            }

            if (orderItems.length === 0) {
              await supabaseAdmin.from("debug_webhooks").insert({
                direction: "inbound",
                raw_payload: { message: messageBody, sender: senderPhone, company: companyName },
                phone_number: phone91,
                error_message: `No SKU Match: ${messageBody.substring(0, 500)}`,
                processed: false,
              });
            }

            const totalWithGst = Math.round(estimatedTotal * 1.18);
            const advanceRequired = Math.max(Math.round((totalWithGst * 0.2) / 1000) * 1000, 1000);

            await supabaseAdmin.from("orders").update({
              sales_order_value: totalWithGst,
              advance_required: advanceRequired,
              parser_confidence: orderItems.length > 0 ? Math.min(...orderItems.map((i) => i.confidence)) : null,
            }).eq("id", draftOrder.id);

            piSent = await sendPiNotificationsAndCrm({
              supabaseAdmin,
              draftOrderId: draftOrder.id,
              companyName,
              phone91,
              companyId,
              accountManagerId,
              messageBody,
              piItems,
              totalWithGst,
              isShadowClient: false,
              crmOutcome: "draft_order_created",
              crmNotesSuffix: `Draft order ${draftOrder.id.slice(0, 8)} auto-created. ${piItems.length > 0 ? `Items: ${piItems.map((i) => `${i.name} x ${i.qty}`).join(", ")}.` : "No SKU match - manual review."}`,
            });
          }
        }
      }
      }
    } else if (messageBody && companyId && !hasOrderIntent) {
      // Core-C owns all autonomous non-order acknowledgements. It applies
      // deterministic disclosure checks, idempotency, case/task lineage and
      // the durable operator-reply outbox. The webhook must only capture
      // inbound evidence here; sending directly would bypass that authority.
      console.log(
        `[WA-GOV] Direct non-order reply suppressed for company ${companyId}; governed Core-C receipt path owns outbound acknowledgement.`,
      );
    }

    if (waAutoOrderWritesEnabled) {
      const cutoff48h = new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString();
      const { data: staleDrafts } = await supabaseAdmin
        .from("orders")
        .select("id")
        .eq("status", "draft")
        .lte("sales_order_value", 0)
        .lt("created_at", cutoff48h)
        .limit(50);

      if (staleDrafts && staleDrafts.length > 0) {
        const staleIds = staleDrafts.map((d: any) => d.id);
        await supabaseAdmin.from("orders").update({ status: "cancelled" }).in("id", staleIds);
        console.log(`Archived ${staleIds.length} stale draft orders`);
      }
    }

    // Every required step has finished: record completion so later retries are plain duplicates.
    if (messageId) {
      await recordInboundProcessingComplete(supabaseAdmin, messageId, phone91 || senderPhone || null);
    }

    inboundReturn(new Response(
      JSON.stringify({
        ok: true,
        company: companyName,
        company_id: companyId,
        sender_type: sender.type,
        message_intent: messageIntent,
        order_intent: hasOrderIntent,
        draft_order_id: draftOrderId,
        pi_sent: piSent,
        attachment: attachmentUrl,
        shadow_client: false,
        identity_resolution_status: companyResolution.resolutionStatus,
        identity_match_method: companyResolution.matchMethod,
        forwarded_message: payloadIdentity.isForwarded,
        document_parsed: !!documentParseResult?.invoiceRef,
      }),
      { status: 200, headers: safeWebhookHeaders() }
    ));
  } catch (e) {
    if (e && typeof e === "object" && (e as { tag?: string }).tag === "inbound_response") {
      const response = (e as { response: Response }).response;
      if (response.status >= 500) return response;
      const body = await response.json() as Record<string, unknown>;
      inboundResults.push({ status: response.status, body });
      continue;
    }
    const msg = e instanceof Error ? e.message : "Unexpected error";
    console.error("whatsapp-webhook error:", msg);

    try {
      await supabaseAdmin.from("debug_webhooks").insert({
        direction: "inbound",
        raw_payload: { error: msg },
        error_message: msg,
        processed: false,
      });
    } catch { /* swallow */ }

    return new Response(JSON.stringify({ error: msg }), {
      status: 500,
      headers: safeWebhookHeaders(),
    });
  }
  }

  if (persistedStatusBatch) {
    return new Response(
      JSON.stringify({
        ok: true,
        event: "mixed",
        ...(statusQuarantineCount ? { quarantined_status_elements: statusQuarantineCount } : {}),
        count: persistedStatusBatch.count,
        updated: persistedStatusBatch.updated,
        ignored: persistedStatusBatch.ignored,
        unmatched: persistedStatusBatch.unmatched,
        quarantined: persistedStatusBatch.quarantined,
        inbound_processed: inboundResults.length,
        inbound: inboundResults.length === 1
          ? inboundResults[0].body
          : inboundResults.map((entry) => entry.body),
      }),
      { status: 200, headers: safeWebhookHeaders() },
    );
  }

  if (inboundResults.length === 0) {
    return new Response(JSON.stringify({ ok: true, skipped: "no_inbound_work" }), {
      status: 200, headers: safeWebhookHeaders(),
    });
  }

  const lastInbound = inboundResults[inboundResults.length - 1];
  if (inboundResults.length === 1) {
    return new Response(JSON.stringify(lastInbound.body), {
      status: lastInbound.status,
      headers: safeWebhookHeaders(),
    });
  }

  return new Response(
    JSON.stringify({
      ok: true,
      event: "inbound_batch",
      inbound_processed: inboundResults.length,
      results: inboundResults.map((entry) => entry.body),
    }),
    { status: 200, headers: safeWebhookHeaders() },
  );
}

