export type WebhookIdentityContext = {
  contactId: string;
  profileName?: string | null;
  messageBody?: string | null;
  senderIsStaffProxy: boolean;
  explicitCompanyId?: string | null;
  isForwarded?: boolean;
  forwardedFromPhone?: string | null;
  originalCommunicatorPhone?: string | null;
};

// Constant literal (no dynamic RegExp construction). Global flag: `String.prototype.match` resets
// lastIndex itself, so sharing this instance across calls is safe.
const GST_PATTERN = /\b([0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z])\b/gi;

/** Lightweight company-name extraction for governed exact-name candidate only. */
export function extractCompanyNameFromText(text: string): string | null {
  if (!text) return null;
  const patterns = [
    /(?:from|for|m\/s\.?|client|company)\s*[:\-]?\s*([A-Z][A-Za-z0-9 &.\-]{2,40})/i,
    /([A-Z][A-Za-z]+(?:\s+[A-Z][A-Za-z]+){0,3})\s+(?:traders|enterprises|sweets|foods|catering|hotel|restaurant|stores|paharganj|bakery)/i,
  ];
  for (const re of patterns) {
    const m = text.match(re);
    if (m?.[1]) return m[1].trim();
  }
  return null;
}

/** Staff relay messages may name a client explicitly; pass exact candidate to Core RPC. */
export function extractStaffMentionedClient(messageBody: string): string | null {
  if (!messageBody) return null;
  const clientPatterns = [
    /(?:order\s+for|client|customer|party|for\s+M\/s\.?|for)\s+[:\-]?\s*([A-Z0-9][A-Za-z0-9\s&'.]+)/i,
    /([A-Z0-9][A-Za-z0-9\s&'.]{3,})\s+(?:ka|ke|ki|order|wants?|need)/i,
  ];
  for (const pat of clientPatterns) {
    const m = messageBody.match(pat);
    if (m?.[1]) return m[1].trim();
  }
  return null;
}

/** The message's single GSTIN, or null when there is none or several (several are ambiguous). */
export function extractGstFromText(text: string): string | null {
  const all = extractAllGstFromText(text);
  return all.length === 1 ? all[0] : null;
}

/** All GSTIN-shaped tokens in message text (synthetic-format only in tests). */
export function extractAllGstFromText(text: string): string[] {
  if (!text) return [];
  const matches = text.match(GST_PATTERN) ?? [];
  const seen = new Set<string>();
  const out: string[] = [];
  for (const raw of matches) {
    const normalized = raw.toUpperCase();
    if (!seen.has(normalized)) {
      seen.add(normalized);
      out.push(normalized);
    }
  }
  return out;
}

export type PayloadIdentityFields = {
  isForwarded: boolean;
  forwardedFromPhone: string | null;
  originalCommunicatorPhone: string | null;
  explicitCompanyId: string | null;
};

/** Extract forwarded/original-customer provenance without inferring commercial customer. */
export function extractPayloadIdentityFields(payload: Record<string, unknown>): PayloadIdentityFields {
  const entry = (payload?.entry as unknown[] | undefined)?.[0] as Record<string, unknown> | undefined;
  const changes = (entry?.changes as unknown[] | undefined)?.[0] as Record<string, unknown> | undefined;
  const value = changes?.value as Record<string, unknown> | undefined;
  const msg = (value?.messages as unknown[] | undefined)?.[0] as Record<string, unknown> | undefined;
  const context = msg?.context as Record<string, unknown> | undefined;

  const m91 =
    (payload?.payload as Record<string, unknown> | undefined)?.message
      ? (payload.payload as Record<string, unknown>)
      : (payload?.data as Record<string, unknown> | undefined)?.payload
        ? ((payload.data as Record<string, unknown>).payload as Record<string, unknown>)
        : (payload?.payload as Record<string, unknown> | undefined)?.mobile ||
            (payload?.payload as Record<string, unknown> | undefined)?.from ||
            (payload?.payload as Record<string, unknown> | undefined)?.sender
          ? (payload.payload as Record<string, unknown>)
          : null;

  const message = (m91?.message as Record<string, unknown> | undefined) ?? {};
  const m91Context = (message?.context as Record<string, unknown> | undefined) ??
    (m91?.context as Record<string, unknown> | undefined);

  const forwardedFlag =
    context?.forwarded === true ||
    context?.frequently_forwarded === true ||
    m91Context?.forwarded === true ||
    m91Context?.frequently_forwarded === true ||
    payload?.forwarded === true ||
    (payload?.data as Record<string, unknown> | undefined)?.forwarded === true;

  const bodyText = typeof msg?.text === "object"
    ? String((msg.text as Record<string, unknown>)?.body ?? "")
    : typeof message?.text === "string"
      ? message.text
      : typeof (message?.text as Record<string, unknown> | undefined)?.body === "string"
        ? String((message.text as Record<string, unknown>).body)
        : "";

  const forwardedBodyHint = /^forwarded message/i.test(bodyText.trim());

  const forwardedFrom =
    stringOrNull(context?.forwarded_from) ??
    stringOrNull(m91Context?.forwarded_from) ??
    stringOrNull(payload?.forwarded_from) ??
    stringOrNull((payload?.data as Record<string, unknown> | undefined)?.forwarded_from) ??
    stringOrNull((payload?.metadata as Record<string, unknown> | undefined)?.forwarded_from);

  const originalCommunicator =
    stringOrNull(context?.original_sender) ??
    stringOrNull(m91Context?.original_sender) ??
    stringOrNull(payload?.original_sender) ??
    stringOrNull((payload?.metadata as Record<string, unknown> | undefined)?.original_sender) ??
    forwardedFrom;

  return {
    isForwarded: forwardedFlag || forwardedBodyHint,
    forwardedFromPhone: forwardedFrom,
    originalCommunicatorPhone: originalCommunicator,
    explicitCompanyId: null,
  };
}

function stringOrNull(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

/** Build governed candidate JSON for whatsapp_resolve_governed_customer. */
export function buildGovernedCandidate(input: WebhookIdentityContext): Record<string, string> {
  const candidate: Record<string, string> = {};

  if (input.senderIsStaffProxy) {
    candidate.sender_is_verified_staff = "true";
  }

  if (input.explicitCompanyId) {
    candidate.company_id = input.explicitCompanyId;
  }

  const mentionedClient = input.senderIsStaffProxy
    ? extractStaffMentionedClient(input.messageBody ?? "")
    : null;
  const extractedName = extractCompanyNameFromText(input.messageBody ?? "");
  const candidateName = mentionedClient ?? extractedName;
  if (candidateName) {
    candidate.company_name = candidateName;
    candidate.business_name = candidateName;
  }

  const gstHints = extractAllGstFromText(input.messageBody ?? "");
  if (gstHints.length > 1) {
    candidate.multiple_gst_hints = "true";
  } else if (gstHints.length === 1) {
    candidate.gst_number = gstHints[0];
  }

  if (input.isForwarded && input.originalCommunicatorPhone) {
    candidate.original_communicator_phone = input.originalCommunicatorPhone;
  }

  return candidate;
}

export function mapGovernedCustomerRow(row: GovernedCustomerRow | null | undefined): WebhookCompanyResolution {
  const status = normalizeResolutionStatus(row?.resolution_status);
  const companyId = row?.company_id ?? null;
  const companyName = row?.business_name ?? "Unknown";
  const accountManagerId =
    typeof row?.details?.account_manager_id === "string"
      ? row.details.account_manager_id
      : null;

  return {
    companyId: status === "RESOLVED" ? companyId : null,
    companyName,
    accountManagerId,
    resolutionStatus: status,
    matchMethod: row?.match_method ?? null,
    details: {
      ...(row?.details ?? {}),
      confidence: row?.confidence ?? null,
      gst_number: row?.gst_number ?? null,
      is_frozen: row?.is_frozen ?? null,
    },
  };
}

function normalizeResolutionStatus(value: string | null | undefined): "RESOLVED" | "AMBIGUOUS" | "UNRESOLVED" {
  if (value === "RESOLVED") return "RESOLVED";
  if (value === "AMBIGUOUS") return "AMBIGUOUS";
  return "UNRESOLVED";
}

/**
 * Resolve commercial customer via Core governed RPC only.
 * Never fuzzy-links, never creates shadow companies, never retargets orders.
 */
const RPC_CANDIDATE_EVIDENCE_KEYS = [
  "company_id",
  "gst_number",
  "multiple_gst_hints",
  "company_name",
  "business_name",
  "name",
] as const;

function hasRpcCandidateEvidence(candidate: Record<string, string>): boolean {
  return RPC_CANDIDATE_EVIDENCE_KEYS.some(
    (key) => typeof candidate[key] === "string" && candidate[key].trim().length > 0,
  );
}

export async function resolveWebhookCompany(
  supabaseAdmin: SupabaseClient,
  input: WebhookIdentityContext,
): Promise<WebhookCompanyResolution> {
  const candidate = buildGovernedCandidate(input);

  if (shouldBlockSenderPhoneInference(input) && !hasRpcCandidateEvidence(candidate)) {
    return {
      companyId: null,
      companyName: input.profileName ?? "Unknown",
      accountManagerId: null,
      resolutionStatus: "UNRESOLVED",
      matchMethod: "SENDER_PHONE_INFERENCE_BLOCKED",
      details: { reason: "relay_or_forwarded_without_candidate" },
    };
  }

  const { data, error } = await supabaseAdmin.rpc(
    "whatsapp_resolve_governed_customer",
    {
      p_contact_id: input.contactId,
      p_candidate: candidate,
    },
  );

  if (error) {
    return {
      companyId: null,
      companyName: input.profileName ?? "Unknown",
      accountManagerId: null,
      resolutionStatus: "UNRESOLVED",
      matchMethod: "RPC_ERROR",
      details: { error: error.message, candidate },
    };
  }

  const row = Array.isArray(data) ? (data[0] as GovernedCustomerRow | undefined) : (data as GovernedCustomerRow | undefined);
  const mapped = mapGovernedCustomerRow(row);

  if (mapped.resolutionStatus !== "RESOLVED") {
    return {
      ...mapped,
      companyName: input.profileName ?? mapped.companyName ?? "Unknown",
      companyId: null,
    };
  }

  if (mapped.companyId) {
    const { data: companyRow } = await supabaseAdmin
      .from("companies")
      .select("account_manager_id")
      .eq("id", mapped.companyId)
      .maybeSingle();
    if (companyRow?.account_manager_id) {
      mapped.accountManagerId = companyRow.account_manager_id;
    }
  }

  return mapped;
}

/** Relay/forwarded senders must not become commercial customer from sender phone alone. */
export function shouldBlockSenderPhoneInference(input: WebhookIdentityContext): boolean {
  return input.senderIsStaffProxy || input.isForwarded === true;
}

import type { SupabaseClient } from "npm:@supabase/supabase-js@2.95.0";
import { resolveInboundAtEdge } from "./resolveInboundAtEdge.ts";

export type StudioFanOutInput = {
  supabaseAdmin: SupabaseClient;
  providerMessageId: string;
  senderPhone: string;
  senderName: string | null;
  messageBody: string;
  messageType?: string;
  mediaCount?: number;
  conversationKey?: string | null;
  correctionOfProviderMessageId?: string | null;
  rawPayload: Record<string, unknown>;
  timestampSec: number | string | null;
  orderLikeHint: boolean;
  commercialRiskReason: string | null;
};

/**
 * Durable Studio/WA-1 ingest. Commercial-risk capture failures must reach the
 * webhook caller so the provider can retry; non-commercial fan-out remains best effort.
 */
export async function fanOutToStudioInbox(input: StudioFanOutInput): Promise<void> {
  const rawTrimmedBody = (input.messageBody ?? "").trim();
  const trimmedBody =
    rawTrimmedBody || `[unreadable ${input.messageType || "media"} attachment]`;
  if (!input.providerMessageId) {
    if (input.orderLikeHint) throw new Error("commercial WhatsApp message is missing provider message id");
    return;
  }

  if (input.orderLikeHint) {
    const { data: existingInbound, error: existingErr } = await input.supabaseAdmin
      .from("whatsapp_inbound_messages")
      .select("id")
      .eq("provider_message_id", input.providerMessageId)
      .maybeSingle();
    if (existingErr) {
      throw new Error(
        `commercial WhatsApp duplicate lookup failed: ${existingErr.message}`,
      );
    }
    if (existingInbound?.id) {
      // Retry after a partial downstream failure: continue into the governed
      // idempotent ingest/capture RPCs. Both correlate by provider_message_id
      // and return the existing persisted record when it was already captured.
      // Throwing here would trap the webhook in permanent 503 replay.
      console.log("[studio-fanout] existing commercial source; retry governed capture");
    }
  }

  let resolver_status: "resolved" | "pending" | "failed" = "pending";
  let resolver_result_json: Record<string, unknown> | null = null;

  try {
    const resolved = await resolveInboundAtEdge(input.supabaseAdmin, trimmedBody);
    if (resolved.resolver_status === "resolved" && resolved.resolver_result_json) {
      resolver_status = "resolved";
      resolver_result_json = resolved.resolver_result_json as unknown as Record<string, unknown>;
    } else if (resolved.resolver_status === "failed") {
      resolver_status = "failed";
    }
  } catch (e) {
    console.warn("[studio-fanout] resolver skipped:", e);
  }

  const tsSec =
    input.timestampSec != null && input.timestampSec !== "" ? Number(input.timestampSec) : NaN;
  const receivedAt =
    Number.isFinite(tsSec) && tsSec > 0 ? new Date(tsSec * 1000).toISOString() : new Date().toISOString();

  const { data: inbound, error } = await input.supabaseAdmin.rpc("ingest_whatsapp_inbound_message", {
    _provider_message_id: input.providerMessageId,
    _sender_phone: input.senderPhone,
    _sender_name: input.senderName,
    _message_body: trimmedBody,
    _message_type: input.messageType || "text",
    _received_at: receivedAt,
    _raw_payload: {
      ...input.rawPayload,
      studio_fanout: true,
      studio_fanout_source: "whatsapp-webhook-legacy",
      commercial_eligible: input.orderLikeHint,
      commercial_risk_reason: input.commercialRiskReason,
    },
    _resolver_status: resolver_status,
    _resolver_result_json: resolver_result_json,
  });

  if (error) {
    console.warn("[studio-fanout] ingest_whatsapp_inbound_message failed:", error.message);
    if (input.orderLikeHint) throw new Error(`commercial WhatsApp ingest failed: ${error.message}`);
    return;
  }

  const inboundRow = Array.isArray(inbound) ? inbound[0] : inbound;
  if (input.orderLikeHint && !inboundRow?.id) {
    throw new Error("commercial WhatsApp ingest returned no inbound message id");
  }
  if (inboundRow?.id && input.orderLikeHint) {
    const mediaCount = Math.max(0, input.mediaCount ?? 0);
    const unreadableMedia =
      rawTrimmedBody === "" && (input.messageType || "text") !== "text";
    const resolvedWithoutProduct =
      resolver_status === "resolved" && !resolver_result_json?.resolved_product_id;
    const awaitingMediaReview = unreadableMedia && mediaCount > 0;
    // Empty-body multimodal ingress is AWAITING_MEDIA until download/worker
    // completes. Do not terminalize as FAILED_INTERPRETATION at capture.
    const interpretationFailed = awaitingMediaReview
      ? false
      : resolvedWithoutProduct || (unreadableMedia && mediaCount === 0);
    let correctionSourceId: string | null = null;
    if (input.correctionOfProviderMessageId) {
      const correctionSource = await input.supabaseAdmin
        .from("whatsapp_inbound_messages")
        .select("id")
        .eq("provider_message_id", input.correctionOfProviderMessageId)
        .maybeSingle();
      correctionSourceId = correctionSource.data?.id ?? null;
    }
    const interpretationFailureKind = interpretationFailed
      ? unreadableMedia
        ? "UNREADABLE_MEDIA"
        : resolvedWithoutProduct
        ? "UNRESOLVED_PRODUCT"
        : null
      : awaitingMediaReview
      ? "AWAITING_MEDIA_REVIEW"
      : null;
    const { error: captureError } = await input.supabaseAdmin.rpc("capture_whatsapp_commercial_fragment", {
      p_source_message_id: inboundRow.id,
      p_packet_id: null,
      p_conversation_key: input.conversationKey,
      p_correction_of_source_message_id: correctionSourceId,
      p_media_count: mediaCount,
      p_interpretation_failed: interpretationFailed,
      p_evidence: {
        ingress: "whatsapp-webhook",
        resolver_status,
        commercial_risk_reason: input.commercialRiskReason,
        fail_open_media_review: awaitingMediaReview ? true : undefined,
        interpretation_failure_kind: interpretationFailureKind,
      },
    });
    if (captureError) {
      console.warn("[studio-fanout] potential-order capture failed:", captureError.message);
      throw new Error(`commercial potential-order capture failed: ${captureError.message}`);
    }
  }
}

