type ScoredCandidate = {
  product_id: string;
  sku: string;
  product_name: string;
  matched_term: string;
  match_source: MatchSource;
  confidence: number;
};

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((t) => t.trim())
    .filter(Boolean);
}

function pickExactAliasWinner(
  catalog: RuntimeCatalog,
  ranked: ScoredCandidate[],
  raw: string,
): ScoredCandidate | undefined {
  const r = raw.trim().toLowerCase().replace(/\s+/g, " ");

  for (const alias of catalog.aliases) {
    const aliasText = alias.alias_text.trim().toLowerCase().replace(/\s+/g, " ");
    if (aliasText !== r) continue;
    const rankedMatch = ranked.find((c) => c.product_id === alias.product_id);
    if (rankedMatch) {
      return {
        ...rankedMatch,
        matched_term: alias.alias_text,
        match_source: "alias",
      };
    }
  }

  const rSorted = [...r.split(/\s+/)].sort().join(" ");
  const sortedMatches = ranked.filter((c) => {
    if (c.match_source !== "alias" && c.match_source !== "short_name") return false;
    const tSorted = [...c.matched_term.trim().toLowerCase().split(/\s+/)].sort().join(" ");
    return tSorted === rSorted;
  });
  return sortedMatches.length === 1 ? sortedMatches[0] : undefined;
}

function considerCandidate(map: Map<string, ScoredCandidate>, candidate: ScoredCandidate) {
  const existing = map.get(candidate.product_id);
  if (!existing || candidate.confidence > existing.confidence) {
    map.set(candidate.product_id, candidate);
  }
}

function scoreEntryTerms(
  entry: CatalogLexiconEntry,
  normalized: ReturnType<typeof normalizeUtterance>,
  catalog: RuntimeCatalog,
): ScoredCandidate | null {
  const queryVariants = [
    normalized.normalized_text,
    normalized.alias_match_text,
    normalized.tokens.join(" "),
  ].filter(Boolean);

  let best: ScoredCandidate | null = null;

  for (const term of entry.terms) {
    let score = 0;

    if (term.source === "sku") {
      score = Math.max(...queryVariants.map((q) => exactSkuScore(q, term.text)));
    } else {
      for (const qv of queryVariants) {
        const qTokens = tokenize(qv);
        const overlap = tokenOverlapScore(qTokens.length ? qTokens : normalized.tokens, term.tokens);
        score = Math.max(score, overlap);
      }
    }

    if (score <= 0) continue;

    let capped =
      term.source === "sku"
        ? score
        : Math.min(0.97, score + (term.source === "alias" ? 0.02 : 0));

    if (term.source === "alias") {
      capped = Math.min(1, capped + exactUtteranceAliasBoost(normalized.raw, term.text));
    }
    capped = Math.min(1, capped + bulkPhraseBoost(normalized.raw, entry.resolved_name, entry.sku));

    const candidate: ScoredCandidate = {
      product_id: entry.product_id,
      sku: entry.sku,
      product_name: entry.resolved_name,
      matched_term: term.text,
      match_source: term.source,
      confidence: capped,
    };

    if (!best || candidate.confidence > best.confidence) {
      best = candidate;
    }
  }

  if (!best) return null;

  let confidence = best.confidence;
  confidence += packCountBoost(normalized.pack_count, entry.search_text, entry.sku);
  confidence += frozenIntentBoost(normalized.tokens, entry.search_text);
  confidence += cheeseIntentBoost(normalized.tokens, entry.search_text);
  const product = catalog.products.find((p) => p.id === entry.product_id);
  if (product) {
    confidence += cashewTartFamilyConfidenceBoost(normalized.raw, product);
  }
  confidence = Math.min(1, Math.max(0, confidence));

  return { ...best, confidence };
}

function isMidyaSingleTokenAmbiguous(
  normalized: ReturnType<typeof normalizeUtterance>,
  catalog: RuntimeCatalog,
): boolean {
  if (normalized.pack_count) return false;
  if (normalized.tokens.length !== 1) return false;
  const token = normalized.tokens[0];
  if (!["midya", "midea", "mediya"].includes(token)) return false;

  const midyaProducts = catalog.products.filter((p) => p.name.toLowerCase().includes("midya"));
  const bulk = midyaProducts.filter((p) => p.name.toLowerCase().includes("bulk"));
  const gift = midyaProducts.filter(
    (p) => p.name.toLowerCase().includes("gift pack") || p.name.toLowerCase().includes("maapet"),
  );
  return bulk.length >= 1 && gift.length >= 1;
}

function isNutAsiyahAmbiguous(
  normalized: ReturnType<typeof normalizeUtterance>,
  catalog: RuntimeCatalog,
): boolean {
  const tokens = normalized.tokens;
  if (tokens.length !== 2) return false;

  const isAsiyah = (t: string) => ["asiyah", "assiyah", "assiya"].includes(t);
  const isCashew = (t: string) => ["cashew", "kaju"].includes(t);
  const isPistachio = (t: string) => ["pistachio", "pista"].includes(t);

  // Dedicated alias order e.g. "assiyah pista" — resolved via exact alias, not generic ambiguity.
  if (isAsiyah(tokens[0]) && (isCashew(tokens[1]) || isPistachio(tokens[1]))) {
    return false;
  }

  if (!isAsiyah(tokens[1])) return false;
  const wantsCashew = isCashew(tokens[0]);
  const wantsPistachio = isPistachio(tokens[0]);
  if (!wantsCashew && !wantsPistachio) return false;

  const qualifiers = ["mor", "chocolate", "beetroot"];
  if (qualifiers.some((q) => normalized.normalized_text.includes(q))) return false;

  const asiyahProducts = catalog.products.filter((p) => {
    const name = p.name.toLowerCase();
    if (!name.includes("asiyah")) return false;
    if (wantsCashew && name.includes("cashew")) return true;
    if (wantsPistachio && name.includes("pistachio")) return true;
    return false;
  });

  return asiyahProducts.length >= 2;
}

/**
 * Phase 2A identify-only resolver — read-only catalogue, no writes.
 */
export function resolveProductUtterance(
  input: string,
  catalog: RuntimeCatalog,
  config: RuntimeResolverConfig = DEFAULT_RUNTIME_RESOLVER_CONFIG,
): ProductUtteranceResolution {
  const normalized = normalizeUtterance(input);
  const lexicon = buildCatalogLexicon(catalog);
  const candidateMap = new Map<string, ScoredCandidate>();

  if (!normalized.normalized_text) {
    return {
      query: input,
      normalized_text: "",
      resolved_product_id: null,
      resolved_sku: null,
      resolved_name: null,
      confidence: 0,
      confidence_band: "LOW",
      action: "ask_clarification",
      reason: "No product matched the normalized utterance.",
      clarification_required: true,
      alternatives: [],
      pack_count: normalized.pack_count,
      order_quantity: extractOrderQuantity(input),
    };
  }

  for (const entry of lexicon) {
    const scored = scoreEntryTerms(entry, normalized, catalog);
    if (scored) considerCandidate(candidateMap, scored);
  }

  let ranked = Array.from(candidateMap.values()).sort((a, b) => b.confidence - a.confidence);
  const {
    collapsed: logicalRanked,
    rawCount,
    logicalGroupCount,
    collapsedDuplicateCount,
  } = collapseCandidatesByLogicalGroup(ranked, catalog, normalized.raw);
  ranked = logicalRanked;

  const midyaAmbiguous = isMidyaSingleTokenAmbiguous(normalized, catalog);
  const exactWinner = midyaAmbiguous ? undefined : pickExactAliasWinner(catalog, ranked, normalized.raw);
  const top = exactWinner ?? ranked[0];
  const second = exactWinner
    ? ranked.find((r) => r.product_id !== exactWinner.product_id)
    : ranked[1];

  const asiyahAmbiguous = isNutAsiyahAmbiguous(normalized, catalog);
  const deltaAmbiguous =
    !exactWinner && top && second
      ? isAmbiguous(top.confidence, second.confidence, config.ambiguity_delta)
      : false;

  const ambiguous = !exactWinner && (midyaAmbiguous || asiyahAmbiguous || deltaAmbiguous);
  const hasCandidates = ranked.length > 0;
  let confidence = top?.confidence ?? 0;

  if (ambiguous && top) {
    confidence = Math.min(confidence, config.min_threshold - 0.01);
  }

  const confidence_band = assignConfidenceBand(
    confidence,
    ambiguous,
    hasCandidates,
    config.high_threshold,
    config.min_threshold,
  );
  const action = actionForBand(confidence_band);
  const clarification_required = action === "ask_clarification";

  const alternatives: RuntimeAlternative[] = ranked.slice(0, config.max_candidates).map((r) => ({
    product_id: r.product_id,
    sku: r.sku,
    product_name: r.product_name,
    confidence: Number(r.confidence.toFixed(4)),
    matched_term: r.matched_term,
    match_source: r.match_source,
  }));

  const reason = buildReason({
    band: confidence_band,
    ambiguous,
    confidence,
    minThreshold: config.min_threshold,
    matchSource: top?.match_source,
    matchedTerm: top?.matched_term,
    resolvedSku: clarification_required ? null : top?.sku,
    candidateCount: rawCount,
    logicalGroupCount,
    collapsedDuplicateCount,
  });

  return {
    query: input,
    normalized_text: normalized.normalized_text,
    resolved_product_id: clarification_required ? null : (top?.product_id ?? null),
    resolved_sku: clarification_required ? null : (top?.sku ?? null),
    resolved_name: clarification_required ? null : (top?.product_name ?? null),
    confidence: Number(confidence.toFixed(4)),
    confidence_band,
    action,
    reason,
    clarification_required,
    alternatives,
    pack_count: normalized.pack_count,
    order_quantity: extractOrderQuantity(input),
  };
}

import type { RuntimeCatalog, RuntimeCatalogAlias, RuntimeCatalogProduct } from "./types.ts";

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((t) => t.trim())
    .filter(Boolean);
}

export type CatalogLexiconEntry = {
  product_id: string;
  sku: string;
  resolved_name: string;
  search_text: string;
  name_tokens: string[];
  terms: Array<{ text: string; tokens: string[]; source: "sku" | "name" | "short_name" | "alias" | "canonical_name" | "category" | "subcategory" }>;
};

export function buildCatalogLexicon(catalog: RuntimeCatalog): CatalogLexiconEntry[] {
  const aliasesByProduct = new Map<string, RuntimeCatalogAlias[]>();
  for (const alias of catalog.aliases) {
    const list = aliasesByProduct.get(alias.product_id) ?? [];
    list.push(alias);
    aliasesByProduct.set(alias.product_id, list);
  }

  return catalog.products.map((product) => {
    const resolved_name = product.product_name ?? product.name;
    const terms: CatalogLexiconEntry["terms"] = [];

    const addTerm = (text: string, source: CatalogLexiconEntry["terms"][number]["source"]) => {
      const trimmed = text.trim();
      if (!trimmed) return;
      terms.push({ text: trimmed, tokens: tokenize(trimmed), source });
    };

    addTerm(product.sku, "sku");
    addTerm(product.name, "name");
    if (product.product_name) addTerm(product.product_name, "name");
    if (product.short_name) addTerm(product.short_name, "short_name");
    if (product.category) addTerm(product.category, "category");
    if (product.subcategory) addTerm(product.subcategory, "subcategory");

    for (const alias of aliasesByProduct.get(product.id) ?? []) {
      addTerm(alias.alias_text, "alias");
      addTerm(alias.canonical_name, "canonical_name");
    }

    const search_text = [
      product.sku,
      product.name,
      product.product_name,
      product.short_name,
      product.category,
      product.subcategory,
      ...(aliasesByProduct.get(product.id) ?? []).flatMap((a) => [a.alias_text, a.canonical_name]),
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    return {
      product_id: product.id,
      sku: product.sku,
      resolved_name,
      search_text,
      name_tokens: tokenize(resolved_name),
      terms,
    };
  });
}

import { productFamilyKey } from "./productFamilies.ts";
import type { RuntimeCatalog, RuntimeCatalogProduct } from "./types.ts";

export type ScoredCandidateLike = {
  product_id: string;
  sku: string;
  product_name: string;
  matched_term: string;
  match_source: string;
  confidence: number;
};

export type CollapsedCandidatesResult<T extends ScoredCandidateLike> = {
  collapsed: T[];
  rawCount: number;
  logicalGroupCount: number;
  collapsedDuplicateCount: number;
};

function normalizeLabel(value: string | null | undefined): string {
  return (value ?? "").trim().toLowerCase().replace(/\s+/g, " ");
}

/** Extract trailing numeric serial from Oasis SKUs e.g. ...-0017 → 17 */
export function skuSerial(sku: string): number {
  const match = sku.match(/(\d+)\s*$/);
  return match ? Number(match[1]) : 0;
}

/** Pack / variant bucket so bulk vs gift remain distinct logical groups. */
export function packVariantIndicator(product: RuntimeCatalogProduct): string {
  const hay = [
    product.sku,
    product.name,
    product.product_name,
    product.short_name,
    product.packaging_code,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  if (hay.includes("gift pack") || hay.includes("gift") && hay.includes("pc")) return "gift_pack";
  if (product.sku.includes("MAAPET") || hay.includes("maapet")) return "maapet";
  if (product.sku.includes("BULK") || hay.includes(" bulk")) return "bulk";
  if (product.packaging_code) return normalizeLabel(product.packaging_code);

  const skuSegment = product.sku.split("-").find((s) =>
    ["BULK", "MAAPET", "LOOSE", "TRAY1KG", "RBOX", "MAPTRAY"].includes(s.toUpperCase()),
  );
  if (skuSegment) return skuSegment.toLowerCase();

  return "default";
}

/** Stable logical group key — duplicate catalogue rows share this key. */
export function logicalGroupKey(product: RuntimeCatalogProduct): string {
  const family = productFamilyKey(product);
  if (family) {
    return `family::${family}`;
  }

  const name = normalizeLabel(product.product_name ?? product.name);
  const short = normalizeLabel(product.short_name);
  const category = normalizeLabel(product.category);
  const subcategory = normalizeLabel(product.subcategory);
  const pack = packVariantIndicator(product);
  return [name, short, category, subcategory, pack].join("::");
}

function isActiveProduct(product: RuntimeCatalogProduct | undefined): boolean {
  if (!product) return false;
  if (product.archived_at) return false;
  if (product.is_active === false) return false;
  return true;
}

function timestampMs(value: string | null | undefined): number {
  if (!value) return 0;
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? ms : 0;
}

function exactAliasMatchScore(rawUtterance: string, matchedTerm: string): number {
  const raw = rawUtterance.trim().toLowerCase().replace(/\s+/g, " ");
  const term = matchedTerm.trim().toLowerCase().replace(/\s+/g, " ");
  if (raw === term) return 2;
  const rawSorted = [...raw.split(" ")].sort().join(" ");
  const termSorted = [...term.split(" ")].sort().join(" ");
  return rawSorted === termSorted ? 1 : 0;
}

function compareRepresentatives<T extends ScoredCandidateLike>(
  a: T,
  b: T,
  productA: RuntimeCatalogProduct | undefined,
  productB: RuntimeCatalogProduct | undefined,
  rawUtterance: string,
): number {
  const activeA = isActiveProduct(productA) ? 1 : 0;
  const activeB = isActiveProduct(productB) ? 1 : 0;
  if (activeA !== activeB) return activeB - activeA;

  const updatedA = Math.max(timestampMs(productA?.updated_at), timestampMs(productA?.created_at));
  const updatedB = Math.max(timestampMs(productB?.updated_at), timestampMs(productB?.created_at));
  if (updatedA !== updatedB) return updatedB - updatedA;

  const serialA = skuSerial(a.sku);
  const serialB = skuSerial(b.sku);
  if (serialA !== serialB) return serialB - serialA;

  if (a.confidence !== b.confidence) return b.confidence - a.confidence;

  const aliasA = exactAliasMatchScore(rawUtterance, a.matched_term);
  const aliasB = exactAliasMatchScore(rawUtterance, b.matched_term);
  if (aliasA !== aliasB) return aliasB - aliasA;

  return a.sku.localeCompare(b.sku);
}

function pickGroupRepresentative<T extends ScoredCandidateLike>(
  group: T[],
  productById: Map<string, RuntimeCatalogProduct>,
  rawUtterance: string,
): T {
  return [...group].sort((a, b) =>
    compareRepresentatives(a, b, productById.get(a.product_id), productById.get(b.product_id), rawUtterance),
  )[0];
}

/**
 * Collapse duplicate/near-duplicate catalogue rows into one representative per logical group.
 * Ambiguity checks should run on collapsed groups, not raw product rows.
 */
export function collapseCandidatesByLogicalGroup<T extends ScoredCandidateLike>(
  candidates: T[],
  catalog: RuntimeCatalog,
  rawUtterance: string,
): CollapsedCandidatesResult<T> {
  const productById = new Map(catalog.products.map((p) => [p.id, p]));
  const byGroup = new Map<string, T[]>();

  for (const candidate of candidates) {
    const product = productById.get(candidate.product_id);
    const key = product ? logicalGroupKey(product) : `unknown::${candidate.product_id}`;
    const list = byGroup.get(key) ?? [];
    list.push(candidate);
    byGroup.set(key, list);
  }

  const collapsed: T[] = [];
  for (const group of byGroup.values()) {
    collapsed.push(pickGroupRepresentative(group, productById, rawUtterance));
  }

  collapsed.sort((a, b) => b.confidence - a.confidence);

  return {
    collapsed,
    rawCount: candidates.length,
    logicalGroupCount: collapsed.length,
    collapsedDuplicateCount: candidates.length - collapsed.length,
  };
}

import type { RuntimeCatalogProduct } from "./types.ts";

/** Accepted SKUs for the Cashew Tart / Tart Cashew product family. */
export const CASHEW_TART_FAMILY_SKUS = [
  "OAS-AS-BKL-0020",
  "OAS-AS-BKL-CSH-BULK-0003",
  "OAS-AS-BKL-CSH-BULK-0004",
] as const;

const CASHEW_TOKENS = new Set(["cashew", "kaju"]);
const TART_TOKENS = new Set(["tart"]);

function nameTokens(product: RuntimeCatalogProduct): string[] {
  return [product.name, product.product_name, product.short_name]
    .filter(Boolean)
    .join(" ")
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((t) => t.trim())
    .filter(Boolean);
}

/** True when catalogue row is Cashew Tart / Tart Cashew (any pack variant). */
export function isCashewTartFamilyProduct(product: RuntimeCatalogProduct): boolean {
  return productFamilyKey(product) === "cashew_tart";
}

export function isCashewTartFamilySku(sku: string | null | undefined): boolean {
  if (!sku) return false;
  return (CASHEW_TART_FAMILY_SKUS as readonly string[]).includes(sku);
}

/**
 * Canonical product-family key for equivalent identity rows.
 * cashew tart = tart cashew = kaju tart = tart kaju → one family.
 */
export function productFamilyKey(product: RuntimeCatalogProduct): string | null {
  const tokens = nameTokens(product);
  const hasCashew = tokens.some((t) => CASHEW_TOKENS.has(t));
  const hasTart = tokens.some((t) => TART_TOKENS.has(t));
  if (hasCashew && hasTart) return "cashew_tart";
  return null;
}

/** Order-independent alias phrases equivalent within the cashew tart family. */
export function isCashewTartFamilyUtterance(text: string): boolean {
  const tokens = text
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter(Boolean);
  if (tokens.length < 2) return false;
  const hasCashew = tokens.some((t) => CASHEW_TOKENS.has(t));
  const hasTart = tokens.some((t) => TART_TOKENS.has(t));
  return hasCashew && hasTart;
}

export function cashewTartFamilyConfidenceBoost(
  rawUtterance: string,
  product: RuntimeCatalogProduct,
): number {
  if (!isCashewTartFamilyUtterance(rawUtterance)) return 0;
  if (!isCashewTartFamilyProduct(product)) return 0;
  return 0.14;
}

import type { ConfidenceBand, ResolverAction } from "./types.ts";

export function isAmbiguous(top: number, second: number | undefined, delta: number): boolean {
  return second != null && top - second < delta;
}

export function assignConfidenceBand(
  confidence: number,
  ambiguous: boolean,
  hasCandidates: boolean,
  highThreshold: number,
  minThreshold: number,
): ConfidenceBand {
  if (!hasCandidates || confidence < minThreshold || ambiguous) return "LOW";
  if (confidence >= highThreshold) return "HIGH";
  return "MEDIUM";
}

export function actionForBand(band: ConfidenceBand): ResolverAction {
  switch (band) {
    case "HIGH":
      return "auto_suggest";
    case "MEDIUM":
      return "operator_review";
    default:
      return "ask_clarification";
  }
}

export function buildReason(opts: {
  band: ConfidenceBand;
  ambiguous: boolean;
  confidence: number;
  minThreshold: number;
  matchSource?: string;
  matchedTerm?: string;
  resolvedSku?: string | null;
  candidateCount: number;
  logicalGroupCount?: number;
  collapsedDuplicateCount?: number;
}): string {
  const {
    band,
    ambiguous,
    confidence,
    minThreshold,
    matchSource,
    matchedTerm,
    resolvedSku,
    candidateCount,
    logicalGroupCount,
    collapsedDuplicateCount = 0,
  } = opts;

  const groupCount = logicalGroupCount ?? candidateCount;

  if (candidateCount === 0) {
    return "No product matched the normalized utterance.";
  }
  if (ambiguous) {
    if (collapsedDuplicateCount > 0) {
      return `Multiple product groups score within ambiguity delta — ${groupCount} group(s) need clarification (duplicate catalogue rows collapsed).`;
    }
    return `Multiple product groups score within ambiguity delta — ${groupCount} group(s) need clarification.`;
  }
  if (collapsedDuplicateCount > 0 && band === "HIGH") {
    if (resolvedSku && matchSource === "sku") {
      return `Matched SKU exactly: ${resolvedSku} (duplicate catalogue rows collapsed into product groups).`;
    }
    if (matchedTerm && matchSource) {
      return `Matched via ${matchSource}: "${matchedTerm}" (${band} confidence ${confidence.toFixed(2)}; duplicate catalogue rows collapsed).`;
    }
  }
  if (confidence < minThreshold) {
    return `Best confidence ${confidence.toFixed(2)} is below ${minThreshold} threshold.`;
  }
  if (resolvedSku && matchSource === "sku") {
    return `Matched SKU exactly: ${resolvedSku}`;
  }
  if (matchedTerm && matchSource) {
    return `Matched via ${matchSource}: "${matchedTerm}" (${band} confidence ${confidence.toFixed(2)})`;
  }
  return `Resolved with ${band} confidence ${confidence.toFixed(2)}`;
}

import { applyPhraseSynonyms } from "./synonymMap.ts";

const FILLERS = new Set([
  "pls",
  "please",
  "want",
  "need",
  "order",
  "give",
  "send",
  "one",
  "some",
  "the",
  "a",
  "an",
  "of",
  "for",
  "me",
  "mujhe",
  "chahiye",
  "dedo",
  "bhejo",
  "kilo",
  "kg",
  "gram",
  "gms",
]);

const UNIT_NOISE = new Set(["pc", "pcs", "piece", "pieces", "pkt", "pack"]);

export interface NormalizedUtterance {
  raw: string;
  normalized_text: string;
  tokens: string[];
  pack_count: number | null;
  /** Retains pack qty for alias matching e.g. "6 pc midya". */
  alias_match_text: string;
}

const SKU_PATTERN = /^OAS-[A-Z0-9-]+$/i;

export function extractPackCount(text: string): number | null {
  const packMatch = text.match(/\b(\d{1,3})\s*(?:pc|pcs|piece|pieces)\b/i);
  return packMatch ? Number(packMatch[1]) : null;
}

export function normalizeUtterance(raw: string): NormalizedUtterance {
  const trimmed = raw.trim();
  if (SKU_PATTERN.test(trimmed)) {
    return {
      raw: trimmed,
      normalized_text: trimmed.toUpperCase(),
      tokens: [trimmed.toUpperCase()],
      pack_count: null,
      alias_match_text: trimmed.toUpperCase(),
    };
  }

  let text = trimmed.toLowerCase();
  text = applyPhraseSynonyms(text);

  let pack_count: number | null = null;
  const packMatch = text.match(/\b(\d{1,3})\s*(?:pc|pcs|piece|pieces)\b/);
  const alias_match_text = packMatch ? text.trim() : text.trim();
  if (packMatch) {
    pack_count = Number(packMatch[1]);
    text = text.replace(packMatch[0], " ").trim();
  }

  const tokens = text
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((t) => t.trim())
    .filter((t) => t.length > 0 && !FILLERS.has(t) && !UNIT_NOISE.has(t));

  return {
    raw: trimmed,
    normalized_text: tokens.join(" "),
    tokens,
    pack_count,
    alias_match_text: alias_match_text.replace(/[^a-z0-9\s-]/g, " ").replace(/\s+/g, " ").trim(),
  };
}

/** Static additive synonym config — no DB migration. */
const TOKEN_SYNONYMS: Readonly<Record<string, readonly string[]>> = {
