  kunefe: ["kunafa", "kunefe"],
  knafeh: ["kunafa", "knafeh"],
  knafa: ["kunafa", "knafa"],
  midya: ["midya", "midea", "mediya"],
  midea: ["midya", "midea"],
  mediya: ["midya", "mediya"],
  assiyah: ["assiyah", "asiyah", "assiya"],
  asiyah: ["assiyah", "asiyah", "assiya"],
  assiya: ["assiyah", "assiya"],
