export type WebhookStatusEvent = {
  status: string;
  providerMessageId: string | null;
  providerErrorCode?: string | number | null;
};

/** Bounded reason codes for provider status elements skipped during decode (no PII). */
export type StatusElementQuarantineReason =
  | "non_object"
  | "missing_status"
  | "invalid_status_type"
  | "status_oversized"
  | "provider_id_oversized";

export type StatusElementQuarantine = {
  reason: StatusElementQuarantineReason;
};

export type WebhookStatusParseResult = {
  events: WebhookStatusEvent[];
  quarantined: StatusElementQuarantine[];
};

export type WebhookBoundaryResult =
  | { ok: false; status: 400 | 401 | 403 | 500; code: string }
  | {
    ok: true;
    payload: any;
    statusEvent: WebhookStatusEvent | null;
    statusEvents: WebhookStatusEvent[];
    statusQuarantined: StatusElementQuarantine[];
  };

const MAX_STATUS_STRING_LEN = 64;
const MAX_PROVIDER_ID_LEN = 128;
const MAX_QUARANTINE_DIAGNOSTICS = 16;

const asRecord = (value: unknown): Record<string, any> | null =>
  value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, any> : null;

const boundedErrorCode = (value: unknown): string | null => {
  if (typeof value !== "string" && typeof value !== "number") return null;
  const code = String(value).replace(/[^a-zA-Z0-9_.:-]/g, "").slice(0, 64);
  return code || null;
};

const pushQuarantine = (
  quarantined: StatusElementQuarantine[],
  reason: StatusElementQuarantineReason,
) => {
  if (quarantined.length < MAX_QUARANTINE_DIAGNOSTICS) {
    quarantined.push({ reason });
  }
};

/** Decode Meta statuses; malformed members are quarantined instead of aborting the batch. */
export function detectWebhookStatusEventsWithQuarantine(payload: any): WebhookStatusParseResult {
  const events: WebhookStatusEvent[] = [];
  const quarantined: StatusElementQuarantine[] = [];
  if (Array.isArray(payload?.entry)) {
    for (const rawEntry of payload.entry) {
      const entry = asRecord(rawEntry);
      if (!Array.isArray(entry?.changes)) continue;
      for (const rawChange of entry.changes) {
        const change = asRecord(rawChange);
        const statuses = change?.value?.statuses;
        if (!Array.isArray(statuses)) continue;
        for (const rawStatus of statuses) {
          const event = asRecord(rawStatus);
          if (!event) {
            pushQuarantine(quarantined, "non_object");
            continue;
          }
          if (typeof event.id === "string" && event.id.length > MAX_PROVIDER_ID_LEN) {
            pushQuarantine(quarantined, "provider_id_oversized");
            continue;
          }
          if (typeof event.status !== "string") {
            pushQuarantine(
              quarantined,
              event.status === undefined || event.status === null ? "missing_status" : "invalid_status_type",
            );
            continue;
          }
          if (event.status.length > MAX_STATUS_STRING_LEN) {
            pushQuarantine(quarantined, "status_oversized");
            continue;
          }
          events.push({
            status: event.status,
            providerMessageId: typeof event.id === "string" ? event.id : null,
            providerErrorCode: boundedErrorCode(event.errors?.[0]?.code),
          });
        }
      }
    }
  }
  if (events.length) return { events, quarantined };
  // Click2API's dedicated status payload; never infer an ID from queue_id.
  const click2apiStatus = payload?.message?.message_status;
  if (typeof click2apiStatus !== "string") return { events, quarantined };
  const id = payload?.response?.messages?.[0]?.id;
  return {
    events: [{
      status: click2apiStatus,
      providerMessageId: typeof id === "string" ? id : null,
      providerErrorCode: boundedErrorCode(payload?.message?.error_code),
    }],
    quarantined,
  };
}

/** Decode all Meta statuses, preserving provider order and per-message association. */
export function detectWebhookStatusEvents(payload: any): WebhookStatusEvent[] {
  return detectWebhookStatusEventsWithQuarantine(payload).events;
}

/** Backward-compatible single-event reader for existing callers/tests. */
export function detectWebhookStatusEvent(payload: any): WebhookStatusEvent | null {
  return detectWebhookStatusEvents(payload)[0] ?? null;
}

export async function authenticateAndParseWebhook(args: {
  rawBody: Uint8Array;
  requestUrl: string;
  signatureHeader: string | null;
  verifyToken: string | undefined;
  appSecret: string | undefined;
}): Promise<WebhookBoundaryResult> {
  const url = new URL(args.requestUrl);
  const source = url.searchParams.get("source");
  const authResult = source === "click2api"
    ? verifyChallengeToken(url.searchParams.get("token"), args.verifyToken)
    : await verifyMetaSignature(args.rawBody, args.signatureHeader, args.appSecret);
  if (!authResult.ok) return authResult;
  let payload: any;
  try {
    payload = JSON.parse(new TextDecoder().decode(args.rawBody));
  } catch {
    return { ok: false, status: 400, code: "invalid_json" };
  }
  const { events: statusEvents, quarantined: statusQuarantined } = detectWebhookStatusEventsWithQuarantine(payload);
  return { ok: true, payload, statusEvent: statusEvents[0] ?? null, statusEvents, statusQuarantined };
}

/** PostgREST/Supabase error shape for whatsapp_messages insert outcomes. */
export type WhatsappMessagesInsertError = {
  code?: string;
  message?: string;
};

export type DurablePersistenceDecision =
  | { ok: true; duplicate: boolean }
  | { ok: false };

/**
 * Decide whether inbound webhook processing may acknowledge provider success.
 * Operational durable ownership requires a whatsapp_messages row (or an
 * authoritative duplicate on provider_message_id).
 */
export function evaluateWhatsappMessagesPersistence(
  requiresDurableOwnership: boolean,
  contactId: string | null | undefined,
  insertError: WhatsappMessagesInsertError | null | undefined,
): DurablePersistenceDecision {
  if (!requiresDurableOwnership) {
    return { ok: true, duplicate: false };
  }
  if (!contactId) {
    return { ok: false };
  }
  if (!insertError) {
    return { ok: true, duplicate: false };
  }
  if (insertError.code === "23505") {
    return { ok: true, duplicate: true };
  }
  return { ok: false };
}

export function durablePersistenceFailed(
  requiresDurableOwnership: boolean,
  contactId: string | null | undefined,
  insertError: WhatsappMessagesInsertError | null | undefined,
  threw: boolean,
): boolean {
  if (threw) return requiresDurableOwnership;
  const decision = evaluateWhatsappMessagesPersistence(
    requiresDurableOwnership,
    contactId,
    insertError,
  );
  return !decision.ok;
}

/**
 * Debug-table direction of the receipt row written once an inbound message has completed
 * every required processing step. Durable ownership (a `whatsapp_messages` row) is NOT
 * completion: the buffer, dispute and media steps happen around it, so a provider retry
 * may only be acknowledged as a plain duplicate when this receipt exists. If the receipt
 * is missing or unreadable the retry safely re-runs the idempotent pipeline instead.
 */
export const INBOUND_COMPLETION_DIRECTION = "inbound_completion";

/** Side-effect families that need a stable per-message identity. */
export type InboundEffectKind = "buffer" | "dispute" | "interaction" | "media";

/**
 * Stable UUIDv8 for one effect of one inbound provider event. Retries and concurrent
 * deliveries derive the same key, so the database primary key rejects the duplicate.
 * Never store the provider identifier in the key or log the unhashed source.
 * The "buffer" kind is byte-compatible with the original buffer-only helper.
 */
export async function stableInboundEffectUuid(
  kind: InboundEffectKind,
  providerMessageId: string,
): Promise<string> {
  const id = String(providerMessageId ?? "").trim();
  if (!id) {
    throw new Error(kind === "buffer" ? "WA_BUFFER_PROVIDER_ID_REQUIRED" : "WA_EFFECT_PROVIDER_ID_REQUIRED");
  }
  const data = new TextEncoder().encode(JSON.stringify([`oasis/wa450/${kind}/v1`, id]));
  const digest = await crypto.subtle.digest("SHA-256", data);
  const bytes = new Uint8Array(digest).slice(0, 16);
  bytes[6] = (bytes[6] & 0x0f) | 0x80;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const value = Array.from(bytes).map((b) => b.toString(16).padStart(2, "0")).join("");
  return [value.slice(0, 8), value.slice(8, 12), value.slice(12, 16),
    value.slice(16, 20), value.slice(20)].join("-");
}

/** Stable UUIDv8 key for one inbound provider event's debounced buffer row. */
export function stableInboundBufferUuid(providerMessageId: string): Promise<string> {
  return stableInboundEffectUuid("buffer", providerMessageId);
}

/**
 * Deterministic storage object name for one inbound attachment, so a replay addresses the
 * same object instead of uploading a new copy. Provider media is immutable per message id.
 */
export async function inboundMediaObjectName(
  senderKey: string,
  providerMessageId: string,
  extension: string,
): Promise<string> {
  return `${senderKey}/${await stableInboundEffectUuid("media", providerMessageId)}.${extension}`;
}

/** True when a storage upload failed only because the (deterministic) object already exists. */
export function isStorageObjectExistsError(
  error: { statusCode?: string | number; message?: string } | null | undefined,
): boolean {
  if (!error) return false;
  if (String(error.statusCode ?? "") === "409") return true;
  return /already exists|duplicate/i.test(error.message ?? "");
}

